const API = import.meta.env.VITE_API_BASE_URL || '/api/v1';
// EventSource does not send cookies across frontend/backend ports by default.
// Keep one authenticated wrapper so every SSE feature uses the same session.
const BrowserEventSource = window.EventSource;
const EventSource = class extends BrowserEventSource { constructor(url, options = {}) { super(url, { ...options, withCredentials: true }); } };
async function rawApi(path, options = {}) {
  const { silent = false, ...requestOptions } = options;
  const response = await fetch(`${API}${path}`, { credentials: 'include', ...requestOptions, headers: { ...(requestOptions.body ? { 'Content-Type': 'application/json' } : {}), ...(requestOptions.headers || {}) } });
  const type = response.headers.get('content-type') || '';
  const data = type.includes('json') ? await response.json() : { error: `Máy chủ trả về phản hồi không hợp lệ (${response.status}).` };
  if (!response.ok || data.success === false) { const message = data.error?.message || data.error || data.message || 'Có lỗi xảy ra.'; if (!silent) toast.error(message); const error = new Error(message); error.code = data.error?.code || 'API_REQUEST_FAILED'; error.status = response.status; error.requestId = data.meta?.requestId || response.headers.get('x-request-id'); throw error; }
  return data.success === true && Object.prototype.hasOwnProperty.call(data, 'data') ? data.data : data;
}
async function api(path, options = {}) {
  const maxAttempts = path === '/ai/quiz' ? 3 : 1;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try { return await rawApi(path, { ...options, silent: maxAttempts > 1 && attempt < maxAttempts }); }
    catch (error) {
      const retryable = !error.status || error.status === 408 || error.status === 429 || error.status >= 500 || error.code === 'AI_INVALID_RESPONSE';
      if (!retryable || attempt === maxAttempts) { if (maxAttempts > 1 && options.silent !== true) toast.error(error.message); throw error; }
      await new Promise(resolve => setTimeout(resolve, 700 * attempt));
    }
  }
}
const grades = Array.from({ length: 12 }, (_, i) => `Lớp ${i + 1}`);
const levels = ['Dễ', 'Vừa', 'Khó', 'Nâng cao'];
const queryClient = new QueryClient({ defaultOptions: { queries: { staleTime: 30_000, retry: 1, refetchOnWindowFocus: false } } });
function useLoad(path, fallback = []) { const query = useQuery({ queryKey: ['api', path], queryFn: () => api(path), initialData: fallback }); return [query.data, query.refetch, query.isLoading]; }
function Button({ children, ...props }) { return <button className="primary-button" {...props}>{children}</button>; }
function Select({ label, children, ...props }) { return <label className="field">{label}<select {...props}>{children}</select></label>; }
function Notice({ text, onClose }) { return text ? <div className="error" onClick={onClose}>{text}</div> : null; }
function Navigate(props) { const location = useLocation(); return location.pathname === '/' && props.to === '/student' ? <LandingPage /> : <RouterNavigate {...props} />; }

function App() {
  const [view, setView] = useState('student'); const [teacher, setTeacher] = useState(null); const [student, setStudent] = useState(null); const [authOpen, setAuthOpen] = useState(false); const [role, setRole] = useState('student'); const [error, setError] = useState('');
  useEffect(() => { api('/auth/me').then(x => x.teacher && setTeacher(x.teacher)).catch(() => {}); api('/student/me').then(x => x.student && setStudent(x.student)).catch(() => {}); }, []);
  function openTeacher() { if (teacher) setView('teacher'); else { setRole('teacher'); setAuthOpen(true); } }
  return <div className="shell"><aside><div className="brand">✦ quizzz</div><div className="role-label">Học vui · Nhớ lâu</div><button className={view === 'student' ? 'active' : ''} onClick={() => setView('student')}>Trang học sinh</button><button className={view === 'student-room' ? 'active' : ''} onClick={() => setView('student-room')}>Tham gia phòng</button><button className={view === 'assignments-student' ? 'active' : ''} onClick={() => setView('assignments-student')}>Bài tập của tôi</button><button className={view === 'student-class' ? 'active' : ''} onClick={() => setView('student-class')}>Tham gia lớp</button><div className="nav-divider">GIÁO VIÊN</div><button className={view === 'teacher' ? 'active' : ''} onClick={openTeacher}>Tổng quan</button>{teacher && <><button className={view === 'questions' ? 'active' : ''} onClick={() => setView('questions')}>Kho câu hỏi</button><button className={view === 'ai' ? 'active' : ''} onClick={() => setView('ai')}>Tạo câu hỏi bằng AI</button><button className={view === 'quizzes' ? 'active' : ''} onClick={() => setView('quizzes')}>Bộ quiz của tôi</button><button className={view === 'assignments' ? 'active' : ''} onClick={() => setView('assignments')}>Giao bài tập</button><button className={view === 'classes' ? 'active' : ''} onClick={() => setView('classes')}>Lớp học</button><button className={view === 'realtime' ? 'active' : ''} onClick={() => setView('realtime')}>Phòng realtime</button><button className={view === 'reports' ? 'active' : ''} onClick={() => setView('reports')}>Báo cáo kết quả</button></>}</aside><main><header><span>Quizzz</span><div className="header-actions"><span>{teacher ? `Giáo viên: ${teacher.displayName}` : student ? `Học sinh: ${student.nickname}` : 'Không gian học tập'}</span><button className="auth-button" onClick={() => { setRole(teacher ? 'teacher' : 'student'); setAuthOpen(true); }}>{teacher || student ? 'Đổi tài khoản' : 'Đăng nhập'}</button></div></header><Notice text={error} onClose={() => setError('')} />{view === 'student' && <StudentHome onJoin={() => setView('student-room')} />}{view === 'student-room' && <StudentRoom onError={setError} student={student} />}{view === 'assignments-student' && <StudentAssignments onError={setError} student={student} />}{view === 'student-class' && <JoinClass onError={setError} student={student} />}{view === 'teacher' && <TeacherHome teacher={teacher} setView={setView} />}{view === 'questions' && <Questions onError={setError} />}{view === 'ai' && <AiQuiz onError={setError} />}{view === 'quizzes' && <QuizSets onError={setError} />}{view === 'assignments' && <Assignments onError={setError} />}{view === 'classes' && <Classes onError={setError} />}{view === 'realtime' && <Realtime onError={setError} />}{view === 'reports' && <Reports onError={setError} />}</main>{authOpen && <AuthModal role={role} setRole={setRole} onClose={() => setAuthOpen(false)} onSuccess={x => { if (x.teacher) { setTeacher(x.teacher); setView('teacher'); } if (x.student) { setStudent(x.student); setView('student'); } setAuthOpen(false); }} onError={setError} />}</div>;
}
function StudentHome({ onJoin }) { const { t } = useTranslation(); return <section className="landing"><p className="eyebrow">{t('home.eyebrow')}</p><h1>{t('home.title')}</h1><p className="landing-lead">{t('home.description')}</p><div className="landing-actions"><Button onClick={onJoin}>{t('home.join')}</Button><button className="secondary-button" onClick={() => document.getElementById('about').scrollIntoView({ behavior: 'smooth' })}>{t('home.learnMore')}</button></div><div className="feature-grid" id="about"><article><span>⚡</span><strong>{t('home.realtimeTitle')}</strong><small>{t('home.realtimeDescription')}</small></article><article><span>✦</span><strong>{t('home.practiceTitle')}</strong><small>{t('home.practiceDescription')}</small></article><article><span>◒</span><strong>{t('home.resultTitle')}</strong><small>{t('home.resultDescription')}</small></article></div></section>; }
function AuthModal({ onClose, onSuccess, onError }) { const { t } = useTranslation(); const [register, setRegister] = useState(false); const [form, setForm] = useState({ username: '', email: '', phone: '', password: '', confirmPassword: '' }); const submit = async e => { e.preventDefault(); if (register && form.password !== form.confirmPassword) return onError(t('auth.passwordMismatch')); try { const data = register ? await api('/auth/register', { method: 'POST', body: JSON.stringify({ username: form.username, email: form.email, phone: form.phone, password: form.password, displayName: form.username }) }) : await api('/auth/login', { method: 'POST', body: JSON.stringify({ username: form.username, email: form.email, password: form.password }) }); onSuccess(data); } catch (e) { onError(e.message); } }; return <div className="auth-overlay"><form className="auth-card" onSubmit={submit}><button type="button" className="close-auth" onClick={onClose} aria-label={t('common.close')}>×</button><p className="eyebrow">{register ? t('auth.registerEyebrow') : t('auth.eyebrow')}</p><h2>{register ? t('auth.registerTitle') : t('auth.title')}</h2>{register ? <><label>{t('auth.username')}<input required minLength="3" value={form.username} onChange={e => setForm({ ...form, username: e.target.value })} /></label><label>{t('auth.email')}<input type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} /></label><label>{t('auth.phone')}<input type="tel" value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })} /></label><label>{t('auth.password')}<input required minLength="6" type="password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} /></label><label>{t('auth.confirmPassword')}<input required minLength="6" type="password" value={form.confirmPassword} onChange={e => setForm({ ...form, confirmPassword: e.target.value })} /></label></> : <div><label>{t('auth.usernameOrEmail')}<input required value={form.username} onChange={e => setForm({ ...form, username: e.target.value })} /></label><label>{t('auth.password')}<input required type="password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} /></label></div>}<Button type="submit">{register ? t('auth.register') : t('common.signIn')}</Button><GoogleAuthButton label={register ? t('auth.registerWithGoogle') : t('auth.loginWithGoogle')} onSuccess={onSuccess} onError={onError} /><button type="button" className="text-button" onClick={() => setRegister(!register)}>{register ? t('auth.haveAccount') : t('auth.createAccount')}</button></form></div>; }
function TeacherHome({ teacher, setView }) { return <section className="content-page"><p className="eyebrow">BẢNG ĐIỀU KHIỂN GIÁO VIÊN</p><h1>Chào {teacher?.displayName || 'giáo viên'}.</h1><p className="muted-copy">Tạo câu hỏi, xây dựng bộ quiz, tổ chức lớp và theo dõi kết quả học sinh.</p><div className="feature-grid teacher-cards"><article onClick={() => setView('questions')}><strong>Kho câu hỏi</strong><small>Thêm thủ công, sửa xóa và lọc câu hỏi.</small></article><article onClick={() => setView('ai')}><strong>AI tạo câu hỏi</strong><small>Chọn đúng bài trong mục lục để sinh câu hỏi.</small></article><article onClick={() => setView('quizzes')}><strong>Bộ quiz</strong><small>Chọn câu hỏi và cấu hình bộ đề.</small></article><article onClick={() => setView('assignments')}><strong>Giao bài tập</strong><small>Giao quiz cho lớp và xem tiến độ.</small></article></div></section>; }
function QuestionForm({ initial, onSaved, onCancel, onError }) { const [form, setForm] = useState(initial || { question: '', subject: 'Toán học', grade: 'Lớp 4', level: 'Nhận biết', options: ['', '', '', ''], answer: 0, explanation: '', lessonId: '', lessonTitle: '' }); const [lessons, setLessons] = useState([]); useEffect(() => { api(`/curriculum?grade=${encodeURIComponent(form.grade.replace('Lớp ', ''))}&subject=${encodeURIComponent(form.subject)}`).then(x => setLessons(x.lessons || [])).catch(() => {}); }, [form.grade, form.subject]); const save = async e => { e.preventDefault(); try { const data = await api(initial?.id ? `/questions/${initial.id}` : '/questions', { method: initial?.id ? 'PUT' : 'POST', body: JSON.stringify({ ...form, options: form.options.map(x => x.trim()) }) }); onSaved(data); } catch (e) { onError(e.message); } }; return <form className="panel form-grid" onSubmit={save}><h2>{initial ? 'Sửa câu hỏi' : 'Thêm câu hỏi thủ công'}</h2><label className="field wide">Nội dung câu hỏi<textarea required value={form.question} onChange={e => setForm({ ...form, question: e.target.value })} /></label><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{grades.map(x => <option key={x}>{x}</option>)}</Select><Select label="Cấp độ" value={form.level} onChange={e => setForm({ ...form, level: e.target.value })}>{levels.map(x => <option key={x}>{x}</option>)}</Select><Select label="Bài trong mục lục" value={form.lessonId} onChange={e => { const l = lessons.find(x => x.id === e.target.value); setForm({ ...form, lessonId: e.target.value, lessonTitle: l?.title || '' }); }}><option value="">Chưa chọn bài</option>{lessons.map(x => <option key={x.id} value={x.id}>{x.title}</option>)}</Select>{form.options.map((option, i) => <label className="field" key={i}>Đáp án {String.fromCharCode(65 + i)}<input required value={option} onChange={e => { const next = [...form.options]; next[i] = e.target.value; setForm({ ...form, options: next }); }} /></label>)}<Select label="Đáp án đúng" value={form.answer} onChange={e => setForm({ ...form, answer: Number(e.target.value) })}>{form.options.map((_, i) => <option key={i} value={i}>Đáp án {String.fromCharCode(65 + i)}</option>)}</Select><label className="field wide">Giải thích<textarea value={form.explanation} onChange={e => setForm({ ...form, explanation: e.target.value })} /></label><div className="actions wide"><Button type="submit">Lưu câu hỏi</Button>{onCancel && <button type="button" className="secondary-button" onClick={onCancel}>Hủy</button>}</div></form>; }
function Questions({ onError }) { const [items, reload] = useLoad('/questions'); const [editing, setEditing] = useState(null); const [open, setOpen] = useState(false); const [filter, setFilter] = useState({ grade: '', subject: '', level: '', search: '' }); const query = useMemo(() => Object.entries(filter).filter(([, v]) => v).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&'), [filter]); const [filtered, setFiltered] = useState([]); useEffect(() => { api(`/questions${query ? `?${query}` : ''}`).then(x => setFiltered(x.items || [])).catch(() => {}); }, [query]); async function remove(id) { if (!confirm('Xóa câu hỏi này?')) return; try { await api(`/questions/${id}`, { method: 'DELETE' }); reload(); } catch (e) { onError(e.message); } } return <section className="content-page"><div className="title"><div><p className="eyebrow">NGÂN HÀNG</p><h1>Kho câu hỏi</h1></div><Button onClick={() => { setEditing(null); setOpen(true); }}>+ Thêm thủ công</Button></div>{open && <QuestionForm initial={editing} onSaved={() => { setOpen(false); reload(); }} onCancel={() => setOpen(false)} onError={onError} />}<div className="filters"><input placeholder="Tìm theo nội dung..." value={filter.search} onChange={e => setFilter({ ...filter, search: e.target.value })} /><select value={filter.grade} onChange={e => setFilter({ ...filter, grade: e.target.value })}><option value="">Lọc theo khối lớp</option>{grades.map(x => <option key={x}>{x}</option>)}</select><select value={filter.subject} onChange={e => setFilter({ ...filter, subject: e.target.value })}><option value="">Lọc theo môn học</option><option>Toán học</option><option>Tiếng Việt</option></select><select value={filter.level} onChange={e => setFilter({ ...filter, level: e.target.value })}><option value="">Lọc theo cấp độ</option>{levels.map(x => <option key={x}>{x}</option>)}</select></div><div className="question-list">{filtered.map(q => <article key={q.id}><strong>{q.question}</strong><GeometryDiagram geometry={q.geometry} ariaLabel="Hình minh họa cho câu hỏi" /><small>{q.subject} · {q.grade} · {q.level} {q.lessonTitle ? `· ${q.lessonTitle}` : ''}</small><div className="row-actions"><button className="text-button" onClick={() => { setEditing(q); setOpen(true); }}>Sửa</button><button className="text-button danger" onClick={() => remove(q.id)}>Xóa</button></div></article>)}{!filtered.length && <div className="empty">Chưa có câu hỏi phù hợp.</div>}</div></section>; }
function AiQuiz({ onError }) { const [form, setForm] = useState({ grade: '4', subject: 'Toán học', count: 10, difficulty: 'Thông hiểu', questionType: 'multiple-choice' }); const [lessons, setLessons] = useState([]); const [selected, setSelected] = useState([]); const [result, setResult] = useState(null); useEffect(() => { api(`/curriculum?grade=${form.grade}&subject=${encodeURIComponent(form.subject)}`).then(x => setLessons(x.lessons || [])).catch(e => onError(e.message)); }, [form.grade, form.subject]); async function generate(e) { e.preventDefault(); try { setResult(await api('/ai/quiz', { method: 'POST', body: JSON.stringify({ ...form, lessonIds: selected }) })); } catch (e) { onError(e.message); } } async function saveQuestion(q) { try { await api('/questions', { method: 'POST', body: JSON.stringify({ ...q, grade: `Lớp ${form.grade}`, subject: form.subject, options: q.options, answer: q.answer }) }); } catch (e) { onError(e.message); } } return <section className="content-page"><p className="eyebrow">AI ASSISTANT</p><h1>Tạo câu hỏi bằng AI</h1><form className="panel form-grid" onSubmit={generate}><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{Array.from({ length: 12 }, (_, i) => <option key={i}>{i + 1}</option>)}</Select><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Cấp độ" value={form.difficulty} onChange={e => setForm({ ...form, difficulty: e.target.value })}>{levels.map(x => <option key={x}>{x}</option>)}</Select><label className="field">Số câu<input type="number" min="1" max="20" value={form.count} onChange={e => setForm({ ...form, count: e.target.value })} /></label><div className="lesson-picker wide"><strong>Chọn bài trong mục lục (bắt buộc)</strong>{lessons.map(l => <label key={l.id} className="check"><input type="checkbox" checked={selected.includes(l.id)} onChange={e => setSelected(e.target.checked ? [...selected, l.id] : selected.filter(x => x !== l.id))} />{l.title}</label>)}</div><div className="wide"><Button type="submit">✨ Tạo câu hỏi</Button></div></form>{result?.questions?.length > 0 && <div className="question-list"><h2>Câu hỏi AI đã tạo</h2>{result.questions.map((q, i) => <article key={i}><strong>{i + 1}. {q.question}</strong><small>{q.options.join(' · ')}</small><button className="text-button" onClick={() => saveQuestion(q)}>Lưu vào kho</button></article>)}</div>}</section>; }
function QuizSets({ onError }) { const [items, reload] = useLoad('/quiz-sets'); const [questions, setQuestions] = useState([]); const [form, setForm] = useState({ title: '', description: '', subject: '', grade: '', level: '', timeLimitSeconds: 30, questionIds: [] }); const [open, setOpen] = useState(false); const [editingId, setEditingId] = useState(null); useEffect(() => { api('/questions').then(x => setQuestions(x.items || [])).catch(e => onError(e.message)); }, [open]); async function save(e) { e.preventDefault(); try { await api(editingId ? `/quiz-sets/${editingId}` : '/quiz-sets', { method: editingId ? 'PUT' : 'POST', body: JSON.stringify(form) }); setOpen(false); setEditingId(null); setForm({ ...form, title: '', questionIds: [] }); reload(); } catch (e) { onError(e.message); } } async function remove(id) { try { await api(`/quiz-sets/${id}`, { method: 'DELETE' }); reload(); } catch (e) { onError(e.message); } } return <section className="content-page"><div className="title"><div><p className="eyebrow">THƯ VIỆN ĐỀ</p><h1>Bộ quiz của tôi</h1></div><Button onClick={() => { setEditingId(null); setOpen(!open); }}>+ Tạo bộ quiz</Button></div>{open && <form className="panel form-grid" onSubmit={save}><label className="field wide">Tên bộ quiz<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></label><label className="field wide">Mô tả<textarea value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} /></label><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option value="">Tất cả môn</option><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}><option value="">Tất cả khối</option>{grades.map(x => <option key={x}>{x}</option>)}</Select><label className="field">Thời gian/câu (giây)<input type="number" min="10" value={form.timeLimitSeconds} onChange={e => setForm({ ...form, timeLimitSeconds: e.target.value })} /></label><div className="question-picker wide"><strong>Chọn câu hỏi từ kho ({form.questionIds.length})</strong>{questions.map(q => <label className="check" key={q.id}><input type="checkbox" checked={form.questionIds.includes(q.id)} onChange={e => setForm({ ...form, questionIds: e.target.checked ? [...form.questionIds, q.id] : form.questionIds.filter(id => id !== q.id) })} />{q.question} <small>{q.subject} · {q.grade}</small></label>)}</div><div className="wide"><Button type="submit">Lưu bộ quiz</Button></div></form>}<div className="question-list">{items.items?.map(q => <article key={q.id}><strong>{q.title}</strong><small>{q.questionCount} câu · {q.subject || 'Chưa phân loại'} · {q.grade || 'Mọi khối'}</small><button className="text-button" onClick={async () => { const detail = await api(`/quiz-sets/${q.id}`); setEditingId(q.id); setForm({ title: detail.title, description: detail.description || '', subject: detail.subject || '', grade: detail.grade || '', level: detail.level || '', timeLimitSeconds: detail.timeLimitSeconds || 30, questionIds: (detail.questions || []).map(question => question.id) }); setOpen(true); }}>Sửa</button><button className="text-button danger" onClick={() => remove(q.id)}>Xóa</button></article>)}{!items.items?.length && <div className="empty">Chưa có bộ quiz.</div>}</div></section>; }
function Classes({ onError }) { const [data, reload] = useLoad('/classes'); const [form, setForm] = useState({ name: '', grade: 'Lớp 4', subject: 'Toán học' }); const [selected, setSelected] = useState(null); const [members, setMembers] = useState([]); async function create(e) { e.preventDefault(); try { await api('/classes', { method: 'POST', body: JSON.stringify(form) }); setForm({ ...form, name: '' }); reload(); } catch (e) { onError(e.message); } } async function showMembers(id) { setSelected(id); try { setMembers((await api(`/classes/members?classId=${id}`)).items || []); } catch (e) { onError(e.message); } } async function status(studentId, next) { try { await api('/classes/members/status', { method: 'POST', body: JSON.stringify({ classId: selected, studentId, status: next }) }); showMembers(selected); } catch (e) { onError(e.message); } } return <section className="content-page"><div className="title"><div><p className="eyebrow">CỘNG ĐỒNG LỚP HỌC</p><h1>Lớp học</h1></div></div><form className="panel inline-form" onSubmit={create}><input required placeholder="Tên lớp" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /><select value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{grades.map(x => <option key={x}>{x}</option>)}</select><select value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></select><Button type="submit">+ Tạo lớp</Button></form><div className="question-list">{data.items?.map(c => <article key={c.id}><strong>{c.name}</strong><small>{c.grade} · {c.subject} · {c.studentCount} học sinh · Mã mời: <b>{c.inviteCode}</b></small><button className="text-button" onClick={() => showMembers(c.id)}>Quản lý thành viên</button></article>)}</div>{selected && <div className="panel"><h2>Yêu cầu tham gia</h2>{members.map(m => <div className="member-row" key={m.studentId}><span>{m.nickname}</span><small>{m.status}</small>{m.status === 'pending' && <><button className="text-button" onClick={() => status(m.studentId, 'accepted')}>Duyệt</button><button className="text-button danger" onClick={() => status(m.studentId, 'rejected')}>Từ chối</button></>}</div>)}</div>}</section>; }
function Assignments({ onError }) { const { t } = useTranslation(); const [items, reload] = useLoad('/assignments'); const [quizzes, setQuizzes] = useState([]); const [classes, setClasses] = useState([]); const [form, setForm] = useState({ title: '', quizId: '', classId: '', dueAt: '', allowRetry: false, showAnswers: true }); const [results, setResults] = useState(null); useEffect(() => { api('/quiz-sets').then(x => setQuizzes(x.items || [])).catch(() => {}); api('/classes').then(x => setClasses(x.items || [])).catch(() => {}); }, []); async function save(e) { e.preventDefault(); try { await api('/assignments', { method: 'POST', body: JSON.stringify({ ...form, dueAt: form.dueAt ? new Date(form.dueAt).toISOString() : null }) }); setForm({ ...form, title: '' }); reload(); } catch (e) { onError(e.message); } } async function publish(id, status) { try { await api(`/assignments/${id}/status`, { method: 'POST', body: JSON.stringify({ status }) }); reload(); } catch (e) { onError(e.message); } } async function showResults(id) { try { setResults((await api(`/assignments/${id}/results`)).items); } catch (e) { onError(e.message); } } return <section className="content-page"><p className="eyebrow">BÀI TẬP</p><h1>Giao bài tập quiz</h1><form className="panel form-grid" onSubmit={save}><label className="field">Tên bài giao<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></label><Select label="Bộ quiz" required value={form.quizId} onChange={e => setForm({ ...form, quizId: e.target.value })}><option value="">Chọn bộ quiz</option>{quizzes.map(q => <option key={q.id} value={q.id}>{q.title}</option>)}</Select><Select label="Lớp học" required value={form.classId} onChange={e => setForm({ ...form, classId: e.target.value })}><option value="">Chọn lớp</option>{classes.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</Select><label className="field">Hạn nộp<input type="datetime-local" value={form.dueAt} onChange={e => setForm({ ...form, dueAt: e.target.value })} /></label><label className="check"><input type="checkbox" checked={form.allowRetry} onChange={e => setForm({ ...form, allowRetry: e.target.checked })} />{t('quiz.allowRetry')}</label><label className="check"><input type="checkbox" checked={form.showAnswers} onChange={e => setForm({ ...form, showAnswers: e.target.checked })} />{t('quiz.showAnswers')}</label><div className="wide"><Button type="submit">Tạo bài tập</Button></div></form><div className="question-list">{items.items?.map(a => <article key={a.id}><strong>{a.title}</strong><small>{a.quizTitle} · {a.className} · {a.submissionCount} bài nộp · {a.computedStatus}</small><button className="text-button" onClick={() => publish(a.id, a.status === 'published' ? 'closed' : 'published')}>{a.status === 'published' ? 'Đóng bài' : 'Giao bài'}</button><button className="text-button" onClick={() => showResults(a.id)}>Xem kết quả</button></article>)}</div>{results && <div className="panel"><h2>Kết quả học sinh</h2>{results.map(x => <div className="member-row" key={x.id}><span>{x.nickname}</span><span>{x.score}/{x.total} · {x.percentage}%</span></div>)}</div>}</section>; }
function Reports({ onError }) { const [data, setData] = useState(null); useEffect(() => { api('/reports/overview').then(setData).catch(e => onError(e.message)); }, []); return <section className="content-page"><p className="eyebrow">PHÂN TÍCH</p><h1>Báo cáo kết quả</h1><div className="feature-grid report-cards">{[['Câu hỏi', data?.questions], ['Bộ quiz đã giao', data?.assignments], ['Lượt nộp bài', data?.submissions], ['Điểm trung bình', `${data?.average || 0}%`], ['Lớp học', data?.classes]].map(([label, value]) => <article key={label}><strong>{value ?? '—'}</strong><small>{label}</small></article>)}</div></section>; }
function JoinClass({ onError, student }) { const [code, setCode] = useState(''); async function submit(e) { e.preventDefault(); if (!student) return onError('Hãy đăng nhập bằng nickname trước.'); try { await api('/classes/join', { method: 'POST', body: JSON.stringify({ inviteCode: code }) }); setCode(''); } catch (e) { onError(e.message); } } return <section className="content-page"><p className="eyebrow">HỌC SINH</p><h1>Tham gia lớp học</h1><p className="muted-copy">Nhập mã mời do giáo viên cung cấp. Giáo viên sẽ xác nhận yêu cầu của bạn.</p><form className="panel inline-form" onSubmit={submit}><input required value={code} onChange={e => setCode(e.target.value.toUpperCase())} placeholder="Mã mời lớp" /><Button type="submit">Gửi yêu cầu</Button></form></section>; }
function StudentAssignments({ onError, student }) { const { t } = useTranslation(); const [items, setItems] = useState([]); const [active, setActive] = useState(null); const [answers, setAnswers] = useState({}); useEffect(() => { if (student) api('/assignments').then(x => setItems(x.items || [])).catch(e => onError(e.message)); }, [student]); async function open(id) { try { const x = await api(`/assignments/${id}`); setActive(x); } catch (e) { onError(e.message); } } async function submit(e) { e.preventDefault(); const unanswered = active.questions.filter(question => answers[question.id] === undefined).length; if (unanswered && !window.confirm(t('quiz.unanswered', { count: unanswered }))) return; try { const x = await api(`/assignments/${active.assignment.id}`, { method: 'POST', body: JSON.stringify({ answers }) }); setActive({ ...active, submitted: x.attempt }); } catch (e) { onError(e.message); } } if (!student) return <section className="content-page"><h1>Bài tập của tôi</h1><p className="muted-copy">Đăng nhập bằng nickname để xem bài được giao.</p></section>; return <section className="content-page"><p className="eyebrow">HỌC SINH</p><h1>Bài tập của tôi</h1>{active ? <form className="panel quiz-taking" onSubmit={submit}><button type="button" className="secondary-button" onClick={() => setActive(null)}>← Quay lại</button><h2>{active.assignment.title}</h2>{active.submitted ? <div className="result-box">Bạn đã nộp bài: <b>{active.submitted.score}/{active.submitted.total} ({active.submitted.percentage}%)</b>{active.submitted.answerDetails?.length > 0 && <div className="answer-review">{active.submitted.answerDetails.map(detail => <div key={detail.id}><span>{detail.isCorrect ? '✓' : '✗'} {detail.isCorrect ? 'Đúng' : 'Chưa đúng'}</span>{detail.explanation && <small>{detail.explanation}</small>}</div>)}</div>}</div> : <>{active.questions.map((q, i) => <div className="quiz-question" key={q.id}><strong>{i + 1}. {q.question}</strong><GeometryDiagram geometry={q.geometry} ariaLabel="Hình minh họa cho bài tập" />{q.options.map((o, index) => <label className="check" key={index}><input type="radio" name={q.id} onChange={() => setAnswers({ ...answers, [q.id]: index })} />{o}</label>)}</div>)}<Button type="submit">{t('quiz.submit')} ({t('quiz.answered', { answered: active.questions.filter(question => answers[question.id] !== undefined).length, total: active.questions.length })})</Button></>}</form> : <div className="question-list">{items.map(a => <article key={a.id}><strong>{a.title}</strong><small>{a.quizTitle} · {a.className} · {a.submitted ? 'Đã nộp' : a.expired ? 'Đã quá hạn' : 'Chưa làm'}</small>{!a.submitted && !a.expired && <button className="text-button" onClick={() => open(a.id)}>Làm bài</button>}</article>)}{!items.length && <div className="empty">Chưa có bài tập.</div>}</div>}</section>; }
function StudentRoom({ onError, student }) { const [form, setForm] = useState({ code: '', nickname: student?.nickname || '' }); const [room, setRoom] = useState(null); const [player, setPlayer] = useState(null); const [stream, setStream] = useState(null); const [answerState, setAnswerState] = useState(null); async function join(e) { e.preventDefault(); try { const code = form.code.toUpperCase(); const x = await api(`/rooms/${code}/players`, { method: 'POST', body: JSON.stringify({ nickname: form.nickname }) }); setPlayer(x.player); setRoom(x.room); setAnswerState(null); stream?.close(); const s = new EventSource(`${API}/rooms/${code}/events`); s.addEventListener('room', ev => setRoom(JSON.parse(ev.data))); setStream(s); } catch (e) { onError(e.message); } } async function chooseAnswer(index) { const current = room?.currentQuestionData; if (!player || !current || answerState?.questionIndex === current.index) return; try { const result = await api(`/rooms/${room.code}/answer`, { method: 'POST', body: JSON.stringify({ playerId: player.id, playerToken: player.playerToken, answer: index }) }); setAnswerState({ questionIndex: current.index, index, correct: result.correct, points: result.points }); } catch (e) { onError(e.message); } } useEffect(() => () => stream?.close(), [stream]); useEffect(() => { if (answerState && room?.currentQuestionData?.index !== answerState.questionIndex) setAnswerState(null); }, [room?.currentQuestionData?.index]); return <section className="content-page"><p className="eyebrow">QUIZ REALTIME</p><h1>Tham gia phòng quiz</h1>{!room ? <form className="join-card" onSubmit={join}><label>Mã phòng<input required value={form.code} onChange={e => setForm({ ...form, code: e.target.value })} placeholder="VD: ABC123" /></label><label>Nickname<input required minLength="2" value={form.nickname} onChange={e => setForm({ ...form, nickname: e.target.value })} /></label><Button type="submit">Vào phòng →</Button></form> : <div className="room-card"><div className="room-code">{room.code}</div><h2>{room.title}</h2><p>{room.status === 'lobby' ? 'Đã vào phòng. Chờ giáo viên bắt đầu.' : room.status === 'finished' ? 'Trận chơi đã kết thúc.' : 'Trận chơi đang diễn ra.'}</p><div className="room-players-list">{(room.players || []).map(p => <span key={p.id}>{p.nickname}</span>)}</div>{room.currentQuestionData && <div className="live-question"><strong>{room.currentQuestionData.question}</strong><GeometryDiagram geometry={room.currentQuestionData.geometry} ariaLabel="Hình minh họa cho câu hỏi" />{room.currentQuestionData.options.map((o, i) => <button type="button" className={answerState?.index === i ? (answerState.correct ? 'answer-choice correct' : 'answer-choice incorrect') : 'answer-choice'} disabled={Boolean(answerState)} onClick={() => chooseAnswer(i)} key={i}>{String.fromCharCode(65 + i)}. {o}</button>)}{answerState && <small className={answerState.correct ? 'answer-feedback correct' : 'answer-feedback incorrect'}>{answerState.correct ? `Chính xác! +${answerState.points} điểm` : 'Chưa chính xác.'}</small>}</div>}</div>}</section>; }
function Realtime({ onError }) { const [form, setForm] = useState({ title: '', quizId: '', questionCount: 10, timeLimitSeconds: 20, subject: 'all', grade: 'all', level: 'all' }); const [quizzes, setQuizzes] = useState([]); const [room, setRoom] = useState(null); const [stream, setStream] = useState(null); useEffect(() => { api('/quiz-sets').then(x => setQuizzes(x.items || [])).catch(e => onError(e.message)); }, []); async function create(e) { e.preventDefault(); try { const x = await api('/rooms', { method: 'POST', body: JSON.stringify({ ...form, questionCount: Number(form.questionCount), timeLimitSeconds: Number(form.timeLimitSeconds) }) }); setRoom(x.room); const s = new EventSource(`${API}/rooms/${x.room.code}/events`); s.addEventListener('room', ev => setRoom(JSON.parse(ev.data))); setStream(s); } catch (e) { onError(e.message); } } async function action(path) { try { const x = await api(`/rooms/${room.code}/${path}`, { method: 'POST' }); setRoom(x.room); } catch (e) { onError(e.message); } } useEffect(() => () => stream?.close(), [stream]); return <section className="content-page"><p className="eyebrow">GIÁO VIÊN</p><h1>Phòng quiz realtime</h1>{!room ? <form className="panel form-grid" onSubmit={create}><label className="field wide">Tên phòng<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></label><Select label="Bộ quiz có sẵn" required value={form.quizId} onChange={e => { const quiz = quizzes.find(item => item.id === e.target.value); setForm({ ...form, quizId: e.target.value, questionCount: quiz?.questionCount || form.questionCount, subject: quiz?.subject || form.subject, grade: quiz?.grade || form.grade }); }}><option value="">Chọn bộ quiz</option>{quizzes.map(quiz => <option key={quiz.id} value={quiz.id}>{quiz.title} · {quiz.questionCount || 0} câu</option>)}</Select><label className="field">Số câu<input type="number" min="1" max="30" value={form.questionCount} onChange={e => setForm({ ...form, questionCount: e.target.value })} /></label><label className="field">Giây/câu<input type="number" min="10" max="120" value={form.timeLimitSeconds} onChange={e => setForm({ ...form, timeLimitSeconds: e.target.value })} /></label><div className="wide"><Button type="submit">Tạo phòng</Button></div></form> : <div className="room-card"><div className="room-code">{room.code}</div><h2>{room.title}</h2><p>{room.players?.length || 0} người chơi · {room.status}</p><div className="room-players-list">{(room.players || []).map(p => <span key={p.id}>{p.nickname}</span>)}</div>{room.status === 'lobby' ? <Button onClick={() => action('start')}>Bắt đầu</Button> : room.status === 'playing' && <Button onClick={() => action('next')}>Câu tiếp theo</Button>}</div>}</section>; }
function PaginatedLessonPicker({ lessons, selected, onChange, label = 'Chọn bài trong mục lục' }) { const [page, setPage] = useState(1); const pageSize = 20; const pageCount = Math.max(1, Math.ceil(lessons.length / pageSize)); const current = lessons.slice((page - 1) * pageSize, page * pageSize); useEffect(() => { setPage(1); }, [lessons]); const currentIds = current.map(item => item.id); const allCurrent = current.length > 0 && currentIds.every(id => selected.includes(id)); const togglePage = () => onChange(allCurrent ? selected.filter(id => !currentIds.includes(id)) : Array.from(new Set([...selected, ...currentIds]))); return <div className="lesson-picker wide"><div className="lesson-picker-head"><strong>{label} ({selected.length}/{lessons.length})</strong><div className="lesson-actions"><button type="button" className="text-button" onClick={togglePage}>{allCurrent ? 'Bỏ chọn trang này' : 'Chọn tất cả trang này'}</button><span className="page-meta">Trang {page}/{pageCount}</span></div></div>{current.map(lesson => <label key={lesson.id} className="check"><input type="checkbox" checked={selected.includes(lesson.id)} onChange={event => onChange(event.target.checked ? [...selected, lesson.id] : selected.filter(id => id !== lesson.id))} />{lesson.title}</label>)}{!current.length && <small>Chưa có bài học phù hợp.</small>}{pageCount > 1 && <div className="lesson-pagination"><button type="button" className="secondary-button" disabled={page === 1} onClick={() => setPage(page - 1)}>← Trang trước</button>{Array.from({ length: pageCount }, (_, index) => index + 1).map(number => <button type="button" key={number} className={number === page ? 'page-button active' : 'page-button'} onClick={() => setPage(number)}>{number}</button>)}<button type="button" className="secondary-button" disabled={page === pageCount} onClick={() => setPage(page + 1)}>Trang sau →</button></div>}</div>; }
function QuestionFormPaginated({ initial, onSaved, onCancel, onError }) { const [form, setForm] = useState(initial || { question: '', subject: 'Toán học', grade: 'Lớp 4', level: 'Dễ', options: ['', '', '', ''], answer: 0, explanation: '', lessonId: '', lessonTitle: '' }); const [lessons, setLessons] = useState([]); useEffect(() => { api(`/curriculum?grade=${encodeURIComponent(form.grade.replace('Lớp ', ''))}&subject=${encodeURIComponent(form.subject)}`).then(x => setLessons(x.lessons || [])).catch(() => {}); }, [form.grade, form.subject]); const save = async e => { e.preventDefault(); try { const data = await api(initial?.id ? `/questions/${initial.id}` : '/questions', { method: initial?.id ? 'PUT' : 'POST', body: JSON.stringify({ ...form, options: form.options.map(x => x.trim()) }) }); onSaved(data); } catch (e) { onError(e.message); } }; return <form className="panel form-grid" onSubmit={save}><h2>{initial ? 'Sửa câu hỏi' : 'Thêm câu hỏi thủ công'}</h2><label className="field wide">Nội dung câu hỏi<textarea required value={form.question} onChange={e => setForm({ ...form, question: e.target.value })} /></label><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{grades.map(x => <option key={x}>{x}</option>)}</Select><Select label="Độ khó" value={form.level} onChange={e => setForm({ ...form, level: e.target.value })}>{levels.map(x => <option key={x}>{x}</option>)}</Select><PaginatedLessonPicker lessons={lessons} selected={form.lessonId ? [form.lessonId] : []} onChange={ids => { const lesson = lessons.find(item => item.id === ids[0]); setForm({ ...form, lessonId: ids[0] || '', lessonTitle: lesson?.title || '' }); }} />{form.options.map((option, i) => <label className="field" key={i}>Đáp án {String.fromCharCode(65 + i)}<input required value={option} onChange={e => { const next = [...form.options]; next[i] = e.target.value; setForm({ ...form, options: next }); }} /></label>)}<Select label="Đáp án đúng" value={form.answer} onChange={e => setForm({ ...form, answer: Number(e.target.value) })}>{form.options.map((_, i) => <option key={i} value={i}>Đáp án {String.fromCharCode(65 + i)}</option>)}</Select><label className="field wide">Giải thích<textarea value={form.explanation} onChange={e => setForm({ ...form, explanation: e.target.value })} /></label><div className="actions wide"><Button type="submit">Lưu câu hỏi</Button>{onCancel && <button type="button" className="secondary-button" onClick={onCancel}>Hủy</button>}</div></form>; }
QuestionForm = QuestionFormPaginated;
const QuizSetsLegacy = QuizSets;
QuizSets = function QuizSets(props) { return <><AutoQuizPanel {...props} /><QuizSetsLegacy {...props} /></>; };
function AiQuizPaginated({ onError }) { const [form, setForm] = useState({ grade: '4', subject: 'Toán học', count: 10, difficulty: 'Dễ', questionType: 'multiple-choice' }); const [lessons, setLessons] = useState([]); const [selected, setSelected] = useState([]); const [result, setResult] = useState(null); useEffect(() => { api(`/curriculum?grade=${form.grade}&subject=${encodeURIComponent(form.subject)}`).then(x => { setLessons(x.lessons || []); setSelected([]); }).catch(e => onError(e.message)); }, [form.grade, form.subject]); async function generate(e) { e.preventDefault(); if (!selected.length) return onError('Hãy chọn ít nhất một bài trong mục lục.'); try { setResult(await api('/ai/quiz', { method: 'POST', body: JSON.stringify({ ...form, lessonIds: selected }) })); } catch (e) { onError(e.message); } } async function saveQuestion(q) { try { await api('/questions', { method: 'POST', body: JSON.stringify({ ...q, grade: `Lớp ${form.grade}`, subject: form.subject, options: q.options, answer: q.answer }) }); } catch (e) { onError(e.message); } } return <section className="content-page"><p className="eyebrow">AI ASSISTANT</p><h1>Tạo câu hỏi bằng AI</h1><form className="panel form-grid" onSubmit={generate}><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{Array.from({ length: 12 }, (_, i) => <option key={i}>{i + 1}</option>)}</Select><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Độ khó" value={form.difficulty} onChange={e => setForm({ ...form, difficulty: e.target.value })}>{levels.map(x => <option key={x}>{x}</option>)}</Select><label className="field">Số câu<input type="number" min="1" max="20" value={form.count} onChange={e => setForm({ ...form, count: e.target.value })} /></label><PaginatedLessonPicker lessons={lessons} selected={selected} onChange={setSelected} label="Chọn bài trong mục lục (bắt buộc)" /><div className="wide"><Button type="submit">✨ Tạo câu hỏi</Button></div></form>{result?.questions?.length > 0 && <div className="question-list"><h2>Câu hỏi AI đã tạo</h2>{result.questions.map((q, i) => <article key={i}><strong>{i + 1}. {q.question}</strong><small>{q.options.join(' · ')}</small><button className="text-button" onClick={() => saveQuestion(q)}>Lưu vào kho</button></article>)}</div>}</section>; }
AiQuiz = AiQuizPaginated;
function AutoQuizPanel({ onError }) { const [lessons, setLessons] = useState([]); const [selectedLessons, setSelectedLessons] = useState([]); const [form, setForm] = useState({ title: '', grade: 'Lớp 4', subject: 'Toán học', count: 10, timeLimitSeconds: 30, useAI: true, distribution: { Dễ: 0, Vừa: 0, Khó: 0, 'Nâng cao': 0 } }); const [result, setResult] = useState(null); useEffect(() => { const grade = form.grade.replace('Lớp ', ''); api(`/curriculum?grade=${grade}&subject=${encodeURIComponent(form.subject)}`).then(x => { setLessons(x.lessons || []); setSelectedLessons([]); }).catch(e => onError(e.message)); }, [form.grade, form.subject]); const updateDifficulty = (key, value) => setForm({ ...form, distribution: { ...form.distribution, [key]: Math.max(0, Number(value) || 0) } }); async function submit(e) { e.preventDefault(); if (!selectedLessons.length) return onError('Hãy chọn ít nhất một bài trong mục lục.'); try { setResult(await api('/quiz-sets/auto', { method: 'POST', body: JSON.stringify({ ...form, lessonIds: selectedLessons, lessonTitles: lessons.filter(item => selectedLessons.includes(item.id)).map(item => item.title) }) })); } catch (e) { onError(e.message); } } return <div className="panel"><div className="title"><div><p className="eyebrow">AI QUIZ BUILDER</p><h2>Tạo bộ quiz tự động</h2></div><span className="page-meta">Chọn bài, độ khó và số lượng câu</span></div><form className="form-grid" onSubmit={submit}><label className="field wide">Tên bộ quiz<input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="Ví dụ: Ôn tập giữa kỳ lớp 4" /></label><Select label="Khối lớp (bắt buộc)" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{grades.map(x => <option key={x}>{x}</option>)}</Select><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><label className="field">Tổng số câu<input type="number" min="1" max="50" value={form.count} onChange={e => setForm({ ...form, count: Number(e.target.value) || 1 })} /></label><label className="field">Thời gian/câu<input type="number" min="10" value={form.timeLimitSeconds} onChange={e => setForm({ ...form, timeLimitSeconds: Number(e.target.value) || 30 })} /></label><div className="difficulty-grid wide">{levels.map(level => <label className="field" key={level}>{level}<input type="number" min="0" value={form.distribution[level]} onChange={e => updateDifficulty(level, e.target.value)} /></label>)}</div><PaginatedLessonPicker lessons={lessons} selected={selectedLessons} onChange={setSelectedLessons} label="Chọn bài trong mục lục (bắt buộc)" /><label className="check wide"><input type="checkbox" checked={form.useAI} onChange={e => setForm({ ...form, useAI: e.target.checked })} />Dùng AI để chọn câu hỏi phù hợp nhất</label><div className="wide"><Button type="submit">Tạo bộ quiz tự động</Button></div></form>{result && <div className="result-box">Đã tạo bộ quiz với {result.selectedCount} câu ({result.selectionMode === 'ai' ? 'AI lựa chọn' : 'lọc theo quy tắc'}).</div>}</div>; }
function TeacherHomeStitch({ teacher }) { const navigate = useNavigate(); const [questions] = useLoad('/questions'); const [quizzes] = useLoad('/quiz-sets'); const [classes] = useLoad('/classes'); const [assignments] = useLoad('/assignments'); const cards = [{ label: 'Câu hỏi trong kho', value: questions.length, hint: 'Tất cả câu hỏi đã lưu', tone: 'violet', icon: '☷' }, { label: 'Bộ quiz', value: quizzes.items?.length || 0, hint: 'Bộ đề sẵn sàng sử dụng', tone: 'blue', icon: '▤' }, { label: 'Lớp học', value: classes.items?.length || 0, hint: 'Các lớp đang quản lý', tone: 'green', icon: '♧' }, { label: 'Bài tập đã giao', value: assignments.items?.length || 0, hint: 'Theo dõi tiến độ học sinh', tone: 'orange', icon: '↗' }]; return <section className="content-page stitch-dashboard"><div className="dashboard-heading"><div><p className="eyebrow">BẢNG ĐIỀU KHIỂN GIÁO VIÊN</p><h1>Chào {teacher?.displayName || 'giáo viên'} 👋</h1><p className="muted-copy">Tổng quan hoạt động dạy học và các công cụ tạo quiz của bạn.</p></div><button className="secondary-button" onClick={() => window.location.reload()}>↻ Làm mới</button></div><div className="stat-grid">{cards.map(card => <article className={`stat-card ${card.tone}`} key={card.label}><span className="stat-icon">{card.icon}</span><div><small>{card.label}</small><strong>{card.value}</strong><span>{card.hint}</span></div></article>)}</div><div className="dashboard-grid"><article className="dashboard-panel quick-panel"><div className="panel-heading"><div><p className="eyebrow">TẠO NỘI DUNG</p><h2>Bắt đầu nhanh</h2></div><span className="panel-kicker">4 tác vụ</span></div><div className="quick-actions"><button onClick={() => navigate('/teacher/questions')}><span>☷</span><b>Thêm câu hỏi</b><small>Tạo thủ công trong kho</small></button><button onClick={() => navigate('/teacher/questions/ai')}><span>✦</span><b>AI tạo câu hỏi</b><small>Dựa trên mục lục bài học</small></button><button onClick={() => navigate('/teacher/quizzes')}><span>▤</span><b>Tạo bộ quiz</b><small>Chọn câu hỏi phù hợp</small></button><button onClick={() => navigate('/teacher/realtime')}><span>◉</span><b>Mở phòng realtime</b><small>Chơi trực tiếp cùng lớp</small></button></div></article><article className="dashboard-panel activity-panel"><div className="panel-heading"><div><p className="eyebrow">HOẠT ĐỘNG GẦN ĐÂY</p><h2>Bài tập đã giao</h2></div><button className="text-button" onClick={() => navigate('/teacher/assignments')}>Xem tất cả →</button></div>{assignments.items?.slice(0, 4).map(item => <div className="activity-row" key={item.id}><span className="activity-dot" /><div><b>{item.title}</b><small>{item.className} · {item.submissionCount || 0} bài nộp</small></div><span className={`status-pill ${item.computedStatus}`}>{item.computedStatus === 'published' ? 'Đang mở' : item.computedStatus}</span></div>)}{!assignments.items?.length && <div className="empty-state"><span>◌</span><b>Chưa có bài tập</b><small>Giao bài đầu tiên cho lớp học của bạn.</small></div>}</article></div></section>; }
TeacherHome = TeacherHomeStitch;
function RealtimeStitch({ onError }) { const { t } = useTranslation(); const [form, setForm] = useState({ title: '', quizId: '', questionCount: 10, timeLimitSeconds: 20, subject: 'all', grade: 'all', level: 'all', playMode: 'realtime' }); const [quizzes, setQuizzes] = useState([]); const [room, setRoom] = useState(null); const [stream, setStream] = useState(null); const [displayTime, setDisplayTime] = useState(0); const autoNextKey = useRef(null); const timerArmed = useRef(false); useEffect(() => { api('/quiz-sets').then(x => setQuizzes(x.items || [])).catch(e => onError(e.message)); }, []); async function create(e) { e.preventDefault(); if (!form.quizId) return onError('Hãy chọn một bộ quiz trước khi tạo phòng.'); try { const x = await api('/rooms', { method: 'POST', body: JSON.stringify({ ...form, questionCount: Number(form.questionCount), timeLimitSeconds: Number(form.timeLimitSeconds) }) }); setRoom(x.room); const s = new EventSource(`${API}/rooms/${x.room.code}/events`); s.addEventListener('room', event => setRoom(JSON.parse(event.data))); setStream(s); } catch (e) { onError(e.message); } } async function action(path) { try { const x = await api(`/rooms/${room.code}/${path}`, { method: 'POST' }); setRoom(x.room); } catch (e) { onError(e.message); } } useEffect(() => () => stream?.close(), [stream]); useEffect(() => { timerArmed.current = false; setDisplayTime(Number(room?.timeRemaining ?? form.timeLimitSeconds) || 0); if (!room || room.status !== 'playing') return; const timer = window.setInterval(() => setDisplayTime(value => Math.max(0, value - 1)), 1000); return () => window.clearInterval(timer); }, [room?.status, room?.currentQuestionData?.index]); useEffect(() => { if (!room || room.status !== 'playing' || room.playMode !== 'realtime' || !room.currentQuestionData) return; if (displayTime > 0) { timerArmed.current = true; return; } if (!timerArmed.current) return; const key = `${room.id}:${room.currentQuestionData.index}`; if (autoNextKey.current === key) return; autoNextKey.current = key; action('next'); }, [room?.status, room?.playMode, room?.currentQuestionData?.index, room?.timeRemaining, displayTime]); if (!room) return <section className="content-page setup-page"><div className="dashboard-heading"><div><p className="eyebrow">PHÒNG THI REALTIME</p><h1>Chuẩn bị phòng đấu trực tiếp</h1><p className="muted-copy">Thiết lập một trận quiz tương tác và theo dõi học sinh theo thời gian thực.</p></div><span className="setup-badge">● Phòng mới</span></div><form className="setup-layout" onSubmit={create}><div className="setup-main"><article className="dashboard-panel setup-card"><div className="panel-heading"><h2>① Nội dung phòng</h2><span className="panel-kicker">Bắt buộc</span></div><label className="field wide">Tên phòng<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="Ví dụ: Ôn tập Toán lớp 4" /></label><Select label="Bộ quiz có sẵn" required value={form.quizId} onChange={e => { const quiz = quizzes.find(item => item.id === e.target.value); setForm({ ...form, quizId: e.target.value, questionCount: quiz?.questionCount || form.questionCount, subject: quiz?.subject || form.subject, grade: quiz?.grade || form.grade }); }}><option value="">Chọn bộ quiz</option>{quizzes.map(quiz => <option key={quiz.id} value={quiz.id}>{quiz.title} · {quiz.questionCount || 0} câu</option>)}</Select><div className="form-grid"><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}><option value="all">Tất cả khối</option>{grades.map(x => <option key={x}>{x}</option>)}</Select><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option value="all">Tất cả môn</option><option>Toán học</option><option>Tiếng Việt</option></Select></div></article><article className="dashboard-panel setup-card"><div className="panel-heading"><h2>② Cài đặt trận đấu</h2><span className="panel-kicker">Tùy chỉnh</span></div><div className="mode-options" role="radiogroup" aria-label="Chế độ làm bài"><label className={`mode-option ${form.playMode === 'realtime' ? 'selected' : ''}`}><input type="radio" name="playMode" value="realtime" checked={form.playMode === 'realtime'} onChange={() => setForm({ ...form, playMode: 'realtime' })} /><b>Chế độ realtime</b><small>Học sinh trả lời cùng lúc, có bảng xếp hạng trực tiếp.</small></label><label className={`mode-option ${form.playMode === 'self-paced' ? 'selected' : ''}`}><input type="radio" name="playMode" value="self-paced" checked={form.playMode === 'self-paced'} onChange={() => setForm({ ...form, playMode: 'self-paced' })} /><b>Chế độ luyện tập</b><small>Mỗi học sinh làm theo tốc độ riêng.</small></label></div><div className="form-grid compact-grid"><label className="field">Số câu<input type="number" min="1" max="30" value={form.questionCount} onChange={e => setForm({ ...form, questionCount: e.target.value })} /></label><label className="field">Giây/câu<input type="number" min="10" max="120" value={form.timeLimitSeconds} onChange={e => setForm({ ...form, timeLimitSeconds: e.target.value })} /></label></div></article><button className="primary-button setup-submit" type="submit" disabled={!form.quizId}>Tạo phòng và nhận mã →</button></div><aside className="setup-preview dashboard-panel"><span className="preview-label">XEM TRƯỚC PHÒNG</span><div className="preview-code">842 195</div><b>{form.quizId ? quizzes.find(item => item.id === form.quizId)?.title || 'Bộ quiz đã chọn' : 'Chưa chọn bộ quiz'}</b><small>Học sinh tham gia bằng mã hiển thị sau khi tạo.</small><div className="preview-line"><span>Thời lượng</span><b>{form.timeLimitSeconds}s/câu</b></div><div className="preview-line"><span>Số câu</span><b>{form.questionCount} câu</b></div></aside></form></section>; return <section className="content-page realtime-page"><div className="live-header"><div><p className="eyebrow">QUIZ LIVE ARENA <span className="live-dot">{room.status === 'finished' ? t('realtime.ended') : '● ĐANG TRỰC TIẾP'}</span></p><h1>{room.title}</h1></div><div className="live-code-box"><small>MÃ PHÒNG THI</small><strong>{room.code}</strong></div><button className="secondary-button" onClick={() => { stream?.close(); setRoom(null); }}>Kết thúc phòng</button></div><div className="live-layout"><div className="live-stage"><div className="live-question-head"><span>Câu hỏi {Math.min((room.currentQuestion || 0) + 1, 30)} / {room.questionCount || form.questionCount}</span><b>{displayTime}s</b></div>{room.status === 'finished' ? <div className="room-summary"><div className="summary-heading"><div><p className="eyebrow">{t('realtime.ended')}</p><h2>{t('realtime.finishedTitle')}</h2><p className="muted-copy">{t('realtime.finishedDescription')}</p></div><button className="secondary-button" onClick={() => { stream?.close(); setRoom(null); }}>{t('realtime.newRoom')}</button></div><div className="summary-stats"><div><strong>{room.summary?.questionCount || room.questionCount || form.questionCount}</strong><span>{t('realtime.questions')}</span></div><div><strong>{room.summary?.playerCount || room.players?.length || 0}</strong><span>{t('realtime.players')}</span></div><div><strong>{room.summary?.answeredCount || 0}</strong><span>{t('realtime.answers')}</span></div><div><strong>{room.summary?.accuracy || 0}%</strong><span>{t('realtime.accuracy')}</span></div></div><div className="summary-table">{room.leaderboard?.map((player, index) => <div className="summary-row" key={player.id}><b>#{index + 1}</b><span>{player.nickname}</span><small>{player.correctCount || 0}/{player.answeredCount || 0} {t('realtime.correct')}</small><strong>{player.score || 0} {t('realtime.score')}</strong></div>)}</div></div> : room.currentQuestionData ? <div className="live-question-card"><p className="live-question-number">CÂU HỎI HIỆN TẠI</p><h2>{room.currentQuestionData.question}</h2><div className="live-answer-grid">{room.currentQuestionData.options?.map((option, index) => <div className={`live-answer answer-${index}`} key={index}><b>{String.fromCharCode(65 + index)}</b><span>{option}</span></div>)}</div></div> : <div className="live-empty"><span>◉</span><h2>Sẵn sàng bắt đầu?</h2><p>Chia sẻ mã phòng <b>{room.code}</b> cho học sinh rồi bắt đầu trận đấu.</p></div>}{room.status !== 'finished' && <div className="live-controls"><button className="secondary-button" onClick={() => action('start')} disabled={room.status !== 'lobby'}>▶ Bắt đầu</button><button className="primary-button" onClick={() => action('next')} disabled={room.status !== 'playing'}>Câu tiếp theo →</button></div>}</div><aside className="live-sidebar"><article className="leaderboard-card"><div className="panel-heading"><h2>🏆 Bảng xếp hạng</h2><span className="panel-kicker">Top 5</span></div>{room.leaderboard?.slice(0, 5).map((player, index) => <div className="leader-row" key={player.id}><b>{index + 1}</b><span>{player.nickname}</span><strong>{player.score || 0}</strong></div>)}{!room.leaderboard?.length && <div className="empty-state compact"><span>◌</span><small>Chưa có người chơi</small></div>}</article><article className="players-card"><div className="panel-heading"><h2>Danh sách phòng thi</h2><span className="live-dot">● {room.players?.length || 0} người</span></div><div className="player-chips">{room.players?.map(player => <span key={player.id}>{player.nickname}</span>)}</div></article></aside></div></section>; }
Realtime = RealtimeStitch;
const questionSchema = z.object({ question: z.string().trim().min(1, 'Nhập nội dung câu hỏi.'), subject: z.string().min(1), grade: z.string().min(1), level: z.string().min(1), type: z.enum(['multiple-choice', 'essay']).default('multiple-choice'), options: z.array(z.string()).default([]), answer: z.coerce.number().default(-1), explanation: z.string().optional(), lessonId: z.string().min(1, 'Hãy chọn một bài trong mục lục.') }).superRefine((value, context) => { if (value.type !== 'multiple-choice') return; if (value.options.length !== 4 || value.options.some(option => !option.trim())) context.addIssue({ code: z.ZodIssueCode.custom, path: ['options'], message: 'Trắc nghiệm cần đủ 4 đáp án.' }); if (!Number.isInteger(value.answer) || value.answer < 0 || value.answer >= value.options.length) context.addIssue({ code: z.ZodIssueCode.custom, path: ['answer'], message: 'Chọn đáp án đúng.' }); });
function QuestionFormRHF({ initial, onSaved, onCancel, onError }) { const defaults = initial || { question: '', subject: 'Toán học', grade: 'Lớp 4', level: 'Dễ', type: 'multiple-choice', options: ['', '', '', ''], answer: 0, explanation: '', lessonId: '', lessonTitle: '' }; const { register, handleSubmit, setValue, watch, formState: { errors, isSubmitting } } = useForm({ resolver: zodResolver(questionSchema), defaultValues: defaults }); const [lessons, setLessons] = useState([]); const grade = watch('grade'); const subject = watch('subject'); const selectedLesson = watch('lessonId'); useEffect(() => { api(`/curriculum?grade=${encodeURIComponent(grade.replace('Lớp ', ''))}&subject=${encodeURIComponent(subject)}`).then(x => setLessons(x.lessons || [])).catch(e => onError(e.message)); }, [grade, subject]); async function save(values) { try { const lesson = lessons.find(item => item.id === values.lessonId); await api(initial?.id ? `/questions/${initial.id}` : '/questions', { method: initial?.id ? 'PUT' : 'POST', body: JSON.stringify({ ...values, lessonTitle: lesson?.title || initial?.lessonTitle || '' }) }); toast.success(initial ? 'Đã cập nhật câu hỏi' : 'Đã thêm câu hỏi vào kho'); onSaved(); } catch (error) { onError(error.message); } } return <form className="panel form-grid ant-question-form" onSubmit={handleSubmit(save)}><div className="wide form-heading"><div><p className="eyebrow">QUESTION EDITOR</p><h2>{initial ? 'Sửa câu hỏi' : 'Thêm câu hỏi thủ công'}</h2></div><AntTag color="purple">React Hook Form · Zod</AntTag></div><label className="field wide">Nội dung câu hỏi<textarea {...register('question')} />{errors.question && <small className="form-error">{errors.question.message}</small>}</label><label className="field">Môn học<select {...register('subject')}><option>Toán học</option><option>Tiếng Việt</option></select></label><label className="field">Khối lớp<select {...register('grade')}>{grades.map(item => <option key={item}>{item}</option>)}</select></label><label className="field">Độ khó<select {...register('level')}>{levels.map(item => <option key={item}>{item}</option>)}</select></label><label className="field">Hình thức<select {...register('type')}><option value="multiple-choice">Trắc nghiệm</option><option value="essay">Tự luận</option></select></label><div className="wide"><PaginatedLessonPicker lessons={lessons} selected={selectedLesson ? [selectedLesson] : []} onChange={ids => { const id = ids[ids.length - 1] || ''; setValue('lessonId', id, { shouldValidate: true }); setValue('lessonTitle', lessons.find(item => item.id === id)?.title || ''); }} label="Chọn bài trong mục lục (bắt buộc)" />{errors.lessonId && <small className="form-error">{errors.lessonId.message}</small>}</div>{[0, 1, 2, 3].map(index => <label className="field" key={index}>Đáp án {String.fromCharCode(65 + index)}<input {...register(`options.${index}`)} />{errors.options?.[index] && <small className="form-error">{errors.options[index].message}</small>}</label>)}<label className="field">Đáp án đúng<select {...register('answer')}><option value="0">Đáp án A</option><option value="1">Đáp án B</option><option value="2">Đáp án C</option><option value="3">Đáp án D</option></select></label><label className="field wide">Giải thích<textarea {...register('explanation')} /></label><div className="actions wide"><AntButton type="primary" htmlType="submit" loading={isSubmitting}>Lưu câu hỏi</AntButton>{onCancel && <AntButton htmlType="button" onClick={onCancel}>Hủy</AntButton>}</div></form>; }
