function ReportsStitch({ onError }) { const [data, setData] = useState(null); useEffect(() => { api('/reports/overview').then(setData).catch(e => onError(e.message)); }, []); const points = data?.trend || [{ name: 'T1', value: data?.average || 0 }, { name: 'T2', value: data?.average || 0 }, { name: 'T3', value: data?.average || 0 }, { name: 'T4', value: data?.average || 0 }]; const columns = [{ title: 'Chỉ số', dataIndex: 'label', key: 'label' }, { title: 'Giá trị', dataIndex: 'value', key: 'value', render: value => <b>{value}</b> }, { title: 'Trạng thái', key: 'status', render: () => <AntTag color="green">Đang cập nhật</AntTag> }]; const rows = [['Câu hỏi trong kho', data?.questions || 0], ['Bộ quiz đã giao', data?.assignments || 0], ['Lượt nộp bài', data?.submissions || 0], ['Lớp học', data?.classes || 0]].map(([label, value]) => ({ key: label, label, value })); return <section className="content-page reports-page"><div className="dashboard-heading"><div><p className="eyebrow">PHÂN TÍCH HỌC TẬP</p><h1>Thống kê đào tạo</h1><p className="muted-copy">Theo dõi hoạt động câu hỏi, bộ quiz và kết quả học sinh.</p></div><AntButton onClick={() => window.location.reload()}>↻ Làm mới</AntButton></div><div className="stat-grid report-stat-grid"><AntCard><Statistic title="Câu hỏi trong kho" value={data?.questions || 0} prefix={<BookOpen size={18} />} /></AntCard><AntCard><Statistic title="Bộ quiz đã giao" value={data?.assignments || 0} prefix={<ClipboardList size={18} />} /></AntCard><AntCard><Statistic title="Lượt nộp bài" value={data?.submissions || 0} prefix={<Users size={18} />} /></AntCard><AntCard><Statistic title="Điểm trung bình" value={data?.average || 0} suffix="%" /></AntCard><AntCard><Statistic title="Học sinh chưa nộp" value={data?.pendingStudents || 0} /></AntCard><AntCard><Statistic title="Câu hỏi cần xem lại" value={data?.difficultQuestions?.length || 0} /></AntCard></div><div className="reports-grid"><AntCard title="Xu hướng điểm trung bình"><ResponsiveContainer width="100%" height={250}><AreaChart data={points}><defs><linearGradient id="scoreGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#4f46e5" stopOpacity={0.28}/><stop offset="95%" stopColor="#4f46e5" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 3" stroke="#e2e7ff"/><XAxis dataKey="name"/><YAxis/><ChartTooltip/><Area type="monotone" dataKey="value" stroke="#4f46e5" fill="url(#scoreGradient)" strokeWidth={3}/></AreaChart></ResponsiveContainer></AntCard><AntCard title="Tổng quan dữ liệu"><AntTable columns={columns} dataSource={rows} pagination={false} size="small" /></AntCard></div></section>; }
