function AdminManagement({ onError }) { const [users, setUsers] = useState([]); const [classes, setClasses] = useState([]); const [selected, setSelected] = useState(null); const load = () => { api('/admin/users').then(x => setUsers(x.items || [])).catch(() => {}); api('/classes').then(x => setClasses(x.items || [])).catch(() => {}); }; useEffect(load, []); async function promote(id, role) { try { await api(`/admin/users/${id}/role`, { method: 'POST', body: JSON.stringify({ role }) }); load(); } catch (e) { onError(e.message); } } return users.length ? <section className="content-page admin-management"><div className="dashboard-heading"><div><p className="eyebrow">QUẢN TRỊ</p><h1>Quản lý tài khoản</h1><p className="muted-copy">Danh sách giáo viên và học sinh; admin có thể nâng quyền học sinh thành giáo viên.</p></div></div><div className="dashboard-panel"><div className="question-list">{users.map(user => <article key={user.id}><strong>{user.displayName || user.username}</strong><small>{user.email || user.username} · {user.role}</small>{user.role === 'student' && <button className="text-button" onClick={() => promote(user.id, 'teacher')}>Nâng thành giáo viên</button>}{user.role === 'teacher' && <button className="text-button danger" onClick={() => promote(user.id, 'student')}>Hạ về học sinh</button>}</article>)}</div></div><div className="dashboard-panel"><h2>Danh sách lớp</h2>{classes.map(item => <article className="member-row" key={item.id}><span>{item.name}</span><small>{item.grade || 'Chưa chọn khối'} · {item.studentCount || 0} học sinh</small><button className="text-button" onClick={() => setSelected(item.id)}>Thêm học sinh</button></article>)}{selected && <AdminAddStudent classId={selected} onError={onError} onSaved={load} />}</div></section> : null; }
