QuizSets = function QuizSetsReview({ onError }) { const [items, setItems] = useState([]); const [lessons, setLessons] = useState([]); const [candidates, setCandidates] = useState([]); const [selected, setSelected] = useState([]); const [form, setForm] = useState({ title: '', description: '', subject: 'Toán học', grade: 'Lớp 4', count: 10, timeLimitSeconds: 30, lessonIds: [], type: '' }); const [open, setOpen] = useState(false); const load = () => api('/quiz-sets').then(x => setItems(x.items || [])).catch(e => onError(e.message)); useEffect(load, []); useEffect(() => { api(`/curriculum?grade=${encodeURIComponent(form.grade.replace('Lớp ', ''))}&subject=${encodeURIComponent(form.subject)}`).then(x => setLessons(x.lessons || [])).catch(e => onError(e.message)); }, [form.grade, form.subject]); async function loadCandidates() { try { const params = new URLSearchParams(); if (form.subject) params.set('subject', form.subject); if (form.grade) params.set('grade', form.grade); if (form.type) params.set('type', form.type); const result = await api(`/questions?${params}`); setCandidates((result.items || []).filter(item => !selected.some(question => question.id === item.id))); } catch (e) { onError(e.message); } } async function preview(event) { event.preventDefault(); if (!form.lessonIds.length) return onError('Hãy chọn ít nhất một bài học trong mục lục.'); try { const result = await api('/quiz-sets/auto', { method: 'POST', body: JSON.stringify({ ...form, preview: true, lessonTitles: lessons.filter(item => form.lessonIds.includes(item.id)).map(item => item.title), distribution: { Dễ: Number(form.count), Vừa: 0, Khó: 0, 'Nâng cao': 0 } }) }); setSelected(result.questions || []); setOpen(true); await loadCandidates(); } catch (e) { onError(e.message); } } function toggleLesson(id) { setForm(previous => ({ ...previous, lessonIds: previous.lessonIds.includes(id) ? previous.lessonIds.filter(item => item !== id) : [...previous.lessonIds, id] })); } async function save() { if (!selected.length) return onError('Hãy giữ lại ít nhất một câu hỏi.'); try { await api('/quiz-sets', { method: 'POST', body: JSON.stringify({ ...form, questionIds: selected.map(item => item.id) }) }); toast.success('Đã lưu bộ quiz sau khi xem trước.'); setOpen(false); setSelected([]); load(); } catch (e) { onError(e.message); } } async function exportWord() { try { const response = await fetch(`${API}/worksheet/export`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: form.title || 'Phiếu bài tập', subject: form.subject, grade: form.grade, questionIds: selected.map(item => item.id) }) }); if (!response.ok) throw new Error('Không thể xuất phiếu Word.'); const blob = await response.blob(); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `${form.title || 'phieu-bai-tap'}.docx`; anchor.click(); URL.revokeObjectURL(url); } catch (e) { onError(e.message); } } function removeQuestion(question) { setSelected(previous => previous.filter(item => item.id !== question.id)); setCandidates(previous => [...previous, question]); } function updateQuestion(question, value) { const next = { ...question, question: value }; setSelected(previous => previous.map(item => item.id === question.id ? next : item)); } return <section className="content-page"><div className="title"><div><p className="eyebrow">THƯ VIỆN ĐỀ</p><h1>Bộ quiz của tôi</h1><p className="muted-copy">Tạo bằng AI, xem trước, chỉnh sửa, xóa hoặc thêm câu từ kho trước khi lưu và xuất Word.</p></div><Button onClick={() => setOpen(!open)}>+ Tạo bộ quiz</Button></div>{open && <><form className="panel form-grid" onSubmit={preview}><label className="field wide">Tên bộ quiz<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></label><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value, lessonIds: [] })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value, lessonIds: [] })}>{grades.map(item => <option key={item}>{item}</option>)}</Select><Select label="Loại câu hỏi" value={form.type} onChange={e => setForm({ ...form, type: e.target.value })}><option value="">Tất cả</option><option value="multiple-choice">Trắc nghiệm</option><option value="essay">Tự luận</option></Select><label className="field">Số câu AI chọn<input type="number" min="1" max="50" value={form.count} onChange={e => setForm({ ...form, count: Number(e.target.value) || 1 })} /></label><div className="wide filter-group"><b>Chọn bài học trong mục lục</b><div>{lessons.map(item => <label className="check inline-check" key={item.id}><input type="checkbox" checked={form.lessonIds.includes(item.id)} onChange={() => toggleLesson(item.id)} />{item.title}</label>)}</div></div><Button type="submit">Tạo bản xem trước bằng AI</Button></form>{selected.length > 0 && <div className="dashboard-panel"><div className="panel-heading"><h2>Xem trước câu hỏi ({selected.length})</h2><div><Button onClick={loadCandidates}>Chọn thêm từ kho</Button><Button onClick={exportWord}>Xuất phiếu Word</Button><Button type="primary" onClick={save}>Lưu bộ quiz</Button></div></div>{selected.map((question, index) => <article className="quiz-preview-question" key={question.id}><b>{index + 1}.</b><textarea value={question.question} onChange={e => updateQuestion(question, e.target.value)} /><small>{question.subject} · {question.grade} · {question.level} · {question.type === 'essay' ? 'Tự luận' : 'Trắc nghiệm'}</small><button className="text-button danger" onClick={() => removeQuestion(question)}>Xóa câu</button></article>)}{candidates.length > 0 && <div className="question-picker"><h3>Câu hỏi phù hợp để thêm</h3>{candidates.slice(0, 40).map(question => <label className="check" key={question.id}><input type="checkbox" onChange={e => { if (e.target.checked) { setSelected(previous => [...previous, question]); setCandidates(previous => previous.filter(item => item.id !== question.id)); } }} />{question.question}<small>{question.level} · {question.type === 'essay' ? 'Tự luận' : 'Trắc nghiệm'}</small></label>)}</div>}</div>}</>}{!open && <div className="question-list">{items.map(item => <article key={item.id}><strong>{item.title}</strong><small>{item.questionCount} câu · {item.subject || 'Tất cả môn'} · {item.grade || 'Mọi khối'}</small></article>)}</div>}</section>; };
