function StudentRoomStitch({ onError, student }) { const { t } = useTranslation(); const [form, setForm] = useState({ code: '', nickname: student?.nickname || '' }); const [room, setRoom] = useState(null); const [player, setPlayer] = useState(null); const [stream, setStream] = useState(null); const [answerState, setAnswerState] = useState(null); const [displayTime, setDisplayTime] = useState(0); async function join(e) { e.preventDefault(); try { const code = form.code.toUpperCase(); const x = await api(`/rooms/${code}/players`, { method: 'POST', body: JSON.stringify({ nickname: form.nickname }) }); setPlayer(x.player); setRoom(x.room); setAnswerState(null); stream?.close(); const source = new EventSource(`${API}/rooms/${code}/events?playerId=${encodeURIComponent(x.player.id)}`); source.addEventListener('room', event => setRoom(JSON.parse(event.data))); setStream(source); toast.success('Đã vào phòng quiz'); } catch (error) { onError(error.message); } } async function chooseAnswer(index) { const current = room?.currentQuestionData; if (!player || !current || answerState?.questionIndex === current.index) return; setAnswerState({ questionIndex: current.index, index, pending: true }); try { const result = await api(`/rooms/${room.code}/answer`, { method: 'POST', body: JSON.stringify({ playerId: player.id, playerToken: player.playerToken, answer: index }) }); setAnswerState({ questionIndex: current.index, index, correct: result.correct, points: result.points }); if (result.currentQuestionData) setRoom(previous => ({ ...previous, currentQuestionData: result.currentQuestionData })); } catch (error) { setAnswerState(null); onError(error.message); } } useEffect(() => () => stream?.close(), [stream]); useEffect(() => { setDisplayTime(Number(room?.timeRemaining ?? 0) || 0); if (!room || room.status !== 'playing') return; const timer = window.setInterval(() => setDisplayTime(value => Math.max(0, value - 1)), 1000); return () => window.clearInterval(timer); }, [room?.status, room?.currentQuestionData?.index]); useEffect(() => { if (answerState && room?.currentQuestionData?.index !== answerState.questionIndex) setAnswerState(null); }, [room?.currentQuestionData?.index]); return <section className="content-page student-lobby-page"><div className="dashboard-heading"><div><p className="eyebrow">STUDENT LOBBY</p><h1>Phòng chờ thi đấu</h1><p className="muted-copy">Nhập mã phòng hoặc quét QR để tham gia cùng lớp.</p></div><AntTag color="green">● SSE realtime</AntTag></div>{!room ? <motion.form initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="join-card lobby-join-card" onSubmit={join}><div className="join-card-icon"><Radio size={26}/></div><h2>Tham gia phòng quiz</h2><label>Mã phòng<input required value={form.code} onChange={e => setForm({ ...form, code: e.target.value.toUpperCase() })} placeholder="VD: 849201" /></label><label>Nickname<input required minLength="2" value={form.nickname} onChange={e => setForm({ ...form, nickname: e.target.value })} placeholder="Tên hiển thị của bạn" /></label><AntButton type="primary" htmlType="submit" block>Vào phòng →</AntButton></motion.form> : <motion.div initial={{ opacity: 0, scale: .98 }} animate={{ opacity: 1, scale: 1 }} className="student-room-grid"><article className="dashboard-panel qr-panel"><p className="eyebrow">MÃ PHÒNG THAM GIA</p><div className="student-room-code">{room.code}</div><QRCodeSVG value={`${window.location.origin}/student/room?code=${room.code}`} size={180} bgColor="#ffffff" fgColor="#312e81" level="M" /><small>Quét mã bằng camera điện thoại để vào nhanh.</small><button className="secondary-button" onClick={() => navigator.clipboard?.writeText(room.code)}>Sao chép mã phòng</button></article><article className="dashboard-panel lobby-players"><div className="panel-heading"><div><p className="eyebrow">PHÒNG CHỜ</p><h2>{room.title}</h2></div><AntTag color="green">{room.players?.length || 0} người chơi</AntTag></div><p className="muted-copy">{room.status === 'lobby' ? 'Đã vào phòng. Chờ giáo viên bắt đầu trận đấu.' : room.status === 'finished' ? 'Trận đấu đã kết thúc.' : 'Trận đấu đang diễn ra.'}</p><div className="player-chips light-player-chips">{room.players?.map(player => <span key={player.id}>{player.nickname}</span>)}</div>{room.status === 'finished' ? <div className="student-result"><div className="summary-heading"><div><p className="eyebrow">{t('realtime.ended')}</p><h2>{t('realtime.studentFinishedTitle')}</h2></div></div>{(() => { const result = room.players?.find(item => item.id === player?.id) || {}; const rank = (room.leaderboard || []).findIndex(item => item.id === player?.id) + 1; return <><div className="summary-stats"><div><strong>{result.score || 0}</strong><span>{t('realtime.score')}</span></div><div><strong>{rank > 0 ? `#${rank}` : '—'}</strong><span>{t('realtime.rank')}</span></div><div><strong>{result.correctCount || 0}/{result.answeredCount || 0}</strong><span>{t('realtime.correct')}</span></div><div><strong>{result.accuracy || 0}%</strong><span>{t('realtime.accuracy')}</span></div></div><div className="summary-table">{room.leaderboard?.map((item, index) => <div className={`summary-row ${item.id === player?.id ? 'current' : ''}`} key={item.id}><b>#{index + 1}</b><span>{item.nickname}</span><small>{item.correctCount || 0}/{item.answeredCount || 0} {t('realtime.correct')}</small><strong>{item.score || 0}</strong></div>)}</div></>})()}</div> : room.currentQuestionData && <div className="live-question-card student-question"><p className="live-question-number">CÂU HỎI HIỆN TẠI <span className="student-timer">⏱ {displayTime}s</span></p><h2>{room.currentQuestionData.question}</h2>{room.currentQuestionData.options?.map((option, index) => <button type="button" className={`student-answer ${answerState?.index === index ? (answerState.pending ? 'selected' : answerState.correct ? 'correct' : 'incorrect') : ''}`} disabled={Boolean(answerState) || displayTime <= 0} onClick={() => chooseAnswer(index)} key={index}><b>{String.fromCharCode(65 + index)}</b>{option}</button>)}{answerState && <small className={answerState.correct ? 'answer-feedback correct' : 'answer-feedback incorrect'}>{answerState.correct ? `Chính xác! +${answerState.points} điểm` : 'Chưa chính xác.'}</small>}</div>}</article></motion.div>}</section>; }
StudentRoom = StudentRoomStitch;
function AiQuizI18n({ onError }) { const { t } = useTranslation(); const [form, setForm] = useState({ grade: '4', subject: 'Toán học', count: 10, difficulty: 'Dễ', questionType: 'multiple-choice' }); const [lessons, setLessons] = useState([]); const [selected, setSelected] = useState([]); const [result, setResult] = useState(null); const [isGenerating, setIsGenerating] = useState(false); useEffect(() => { api(`/curriculum?grade=${form.grade}&subject=${encodeURIComponent(form.subject)}`).then(x => { setLessons(x.lessons || []); setSelected([]); }).catch(e => onError(e.message)); }, [form.grade, form.subject]); async function generate(event) { event.preventDefault(); if (!selected.length) return onError(t('ai.selectLesson')); setIsGenerating(true); setResult(null); try { const response = await api('/ai/quiz', { method: 'POST', body: JSON.stringify({ ...form, lessonIds: selected }) }); setResult(response); toast.success(t('ai.generate')); } catch (error) { onError(error.message || t('common.requestFailed')); } finally { setIsGenerating(false); } } async function saveQuestion(question) { try { await api('/questions', { method: 'POST', body: JSON.stringify({ ...question, grade: `Lớp ${form.grade}`, subject: form.subject, options: question.options, answer: question.answer }) }); toast.success(t('common.save')); } catch (error) { onError(error.message || t('common.requestFailed')); } } return <section className="content-page"><p className="eyebrow">AI ASSISTANT</p><h1>{t('ai.title')}</h1><form className="panel form-grid" onSubmit={generate}>{isGenerating && <div className="ai-generation-status wide"><span className="ai-loader"/><div><b>{t('ai.generating')}</b><small>{t('ai.generatingHint')}</small></div></div>}<Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{Array.from({ length: 12 }, (_, i) => <option key={i}>{i + 1}</option>)}</Select><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Độ khó" value={form.difficulty} onChange={e => setForm({ ...form, difficulty: e.target.value })}>{levels.map(x => <option key={x}>{x}</option>)}</Select><label className="field">Số câu<input type="number" min="1" max="20" value={form.count} disabled={isGenerating} onChange={e => setForm({ ...form, count: e.target.value })} /></label><PaginatedLessonPicker lessons={lessons} selected={selected} onChange={setSelected} label={t('ai.selectLesson')} /><div className="wide"><AntButton type="primary" htmlType="submit" loading={isGenerating} disabled={!selected.length}>{isGenerating ? t('ai.generating') : `✨ ${t('ai.generate')}`}</AntButton></div></form>{result?.questions?.length > 0 && <div className="question-list"><h2>Câu hỏi AI đã tạo</h2>{result.questions.map((question, index) => <article key={index}><strong>{index + 1}. {question.question}</strong><small>{question.options.join(' · ')}</small><button className="text-button" onClick={() => saveQuestion(question)}>{t('common.save')}</button></article>)}</div>}</section>; }
AiQuiz = AiQuizI18n;
function AiQuizStream({ onError }) { const { t } = useTranslation(); const [form, setForm] = useState({ grade: '4', subject: 'Toán học', count: 10, difficulty: 'Dễ', questionType: 'multiple-choice' }); const [lessons, setLessons] = useState([]); const [selected, setSelected] = useState([]); const [run, setRun] = useState(null); const [savedJobs, setSavedJobs] = useState([]); const [approvedJobs, setApprovedJobs] = useState([]); const [starting, setStarting] = useState(false); const streamRef = useRef(null); useEffect(() => { api(`/curriculum?grade=${form.grade}&subject=${encodeURIComponent(form.subject)}`).then(x => { setLessons(x.lessons || []); setSelected([]); }).catch(error => onError(error.message)); }, [form.grade, form.subject]); useEffect(() => () => streamRef.current?.close(), []); function updateJob(jobId, patch) { setRun(previous => previous ? { ...previous, jobs: previous.jobs.map(job => job.id === jobId ? { ...job, ...patch } : job) } : previous); } function connect(runId) { streamRef.current?.close(); const source = new EventSource(`${API}/ai/quiz/runs/${runId}/stream`); streamRef.current = source; const parse = event => { try { return JSON.parse(event.data); } catch { return null; } }; source.addEventListener('run.snapshot', event => setRun(parse(event))); source.addEventListener('run.started', event => setRun(previous => ({ ...(previous || {}), ...(parse(event) || {}) }))); source.addEventListener('question.started', event => { const data = parse(event); if (data) updateJob(data.jobId, { status: 'generating', attempts: data.attempt }); }); source.addEventListener('question.retrying', event => { const data = parse(event); if (data) updateJob(data.jobId, { status: 'retrying', attempts: data.attempt, error: data.error }); }); source.addEventListener('question.completed', event => { const data = parse(event); if (data) { updateJob(data.jobId, { status: 'completed', attempts: data.attempt, question: data.question, error: null }); setRun(previous => previous ? { ...previous, completedCount: (previous.completedCount || 0) + 1 } : previous); } }); source.addEventListener('question.failed', event => { const data = parse(event); if (data) { updateJob(data.jobId, { status: 'failed', attempts: data.attempt, error: data.error }); setRun(previous => previous ? { ...previous, failedCount: (previous.failedCount || 0) + 1 } : previous); } }); source.addEventListener('run.progress', event => setRun(parse(event))); source.addEventListener('run.completed', event => { setRun(parse(event)); source.close(); }); source.addEventListener('run.failed', event => { setRun(parse(event)); source.close(); }); source.onerror = () => { if (run?.status !== 'completed' && run?.status !== 'failed') onError('Kết nối stream bị gián đoạn. Hãy mở lại phiên để đồng bộ tiến độ.'); }; } async function start(event) { event.preventDefault(); if (!selected.length) return onError(t('ai.selectLesson')); setStarting(true); try { const created = await api('/ai/quiz/runs', { method: 'POST', body: JSON.stringify({ ...form, count: Number(form.count), lessonIds: selected }) }); setRun(created); connect(created.runId); } catch (error) { onError(error.message); } finally { setStarting(false); } } async function retry(jobId) { try { await api(`/ai/quiz/runs/${run.runId}/jobs/${jobId}/retry`, { method: 'POST' }); updateJob(jobId, { status: 'generating', error: null }); if (!streamRef.current || streamRef.current.readyState === EventSource.CLOSED) connect(run.runId); } catch (error) { onError(error.message); } } function toggleApproval(jobId) { setApprovedJobs(previous => previous.includes(jobId) ? previous.filter(id => id !== jobId) : [...previous, jobId]); } async function saveJob(job) { if (!job.question || !approvedJobs.includes(job.id) || savedJobs.includes(job.id)) return; try { await api('/questions', { method: 'POST', body: JSON.stringify({ ...job.question, subject: job.question.subject || run.subject, grade: job.question.grade || `Lớp ${run.grade}`, level: job.question.level || run.difficulty, lessonId: job.lessonId || '', lessonTitle: job.lessonTitle || job.question.lesson || job.question.lessonTitle || '' }) }); setSavedJobs(previous => [...previous, job.id]); toast.success('Đã lưu câu hỏi vào kho.'); } catch (error) { onError(error.message); } } async function saveAll() { const pending = (run?.jobs || []).filter(job => job.question && approvedJobs.includes(job.id) && !savedJobs.includes(job.id)); await Promise.all(pending.map(saveJob)); } return <section className="content-page"><p className="eyebrow">AI ASSISTANT · STREAM RUN</p><h1>{t('ai.title')}</h1><form className="panel form-grid" onSubmit={start}><Select label="Khối lớp" value={form.grade} onChange={e => setForm({ ...form, grade: e.target.value })}>{Array.from({ length: 12 }, (_, i) => <option key={i}>{i + 1}</option>)}</Select><Select label="Môn học" value={form.subject} onChange={e => setForm({ ...form, subject: e.target.value })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label="Hình thức" value={form.questionType} onChange={e => setForm({ ...form, questionType: e.target.value })}><option value="multiple-choice">Trắc nghiệm</option><option value="essay">Tự luận</option></Select><Select label="Độ khó" value={form.difficulty} onChange={e => setForm({ ...form, difficulty: e.target.value })}>{levels.map(x => <option key={x}>{x}</option>)}</Select><label className="field">Số câu<input type="number" min="1" max="20" disabled={starting} value={form.count} onChange={e => setForm({ ...form, count: e.target.value })} /></label><PaginatedLessonPicker lessons={lessons} selected={selected} onChange={setSelected} label={t('ai.selectLesson')} /><div className="wide"><AntButton type="primary" htmlType="submit" loading={starting} disabled={Boolean(run)}>{starting ? 'Đang mở phiên...' : `✨ ${t('ai.generate')}`}</AntButton></div></form>{run && <div className="ai-run-layout"><article className="dashboard-panel ai-run-summary"><div className="panel-heading"><div><p className="eyebrow">AI GENERATION RUN</p><h2>Đang tạo {run.requestedCount} câu hỏi</h2></div><AntTag color={run.status === 'completed' ? 'green' : run.status === 'failed' ? 'red' : 'blue'}>{run.status}</AntTag></div><div className="ai-progress"><AntProgress percent={Math.round(((run.completedCount || 0) + (run.failedCount || 0)) / run.requestedCount * 100)} status={run.status === 'failed' ? 'exception' : 'active'} /><small>Đã xử lý {(run.completedCount || 0) + (run.failedCount || 0)}/{run.requestedCount} · Thành công {run.completedCount || 0} · Lỗi {run.failedCount || 0}</small>{run.jobs?.some(job => job.question && approvedJobs.includes(job.id) && !savedJobs.includes(job.id)) && <AntButton size="small" onClick={saveAll}>Lưu tất cả câu đã duyệt</AntButton>}</div><div className="ai-job-list">{run.jobs?.map(job => <article className={`ai-job ${job.status}`} key={job.id}><span className="ai-job-index">{job.position}</span><div>{job.question ? <><b>{job.question.question}</b>{job.lessonTitle && <small>Bài: {job.lessonTitle}</small>}<small>{job.question.options?.join(' · ')}</small></> : <><b>{job.status === 'retrying' ? 'Đang thử lại câu hỏi…' : job.status === 'generating' ? 'Đang tạo câu hỏi…' : job.status === 'failed' ? 'Tạo câu hỏi thất bại' : 'Đang chờ xử lý'}</b><small>{job.error || `Lần thử ${job.attempts || 0}`}</small></>}</div><div>{job.status === 'completed' ? (savedJobs.includes(job.id) ? <AntTag color="green">Đã lưu</AntTag> : approvedJobs.includes(job.id) ? <><AntTag color="blue">Đã duyệt</AntTag><AntButton size="small" type="text" onClick={() => toggleApproval(job.id)}>Bỏ duyệt</AntButton></> : <AntButton size="small" onClick={() => toggleApproval(job.id)}>Duyệt câu</AntButton>) : job.status === 'failed' ? <AntButton size="small" onClick={() => retry(job.id)}>Tạo lại</AntButton> : <span className="ai-job-spinner" />}</div></article>)}</div>{['completed', 'failed'].includes(run.status) && <AntButton onClick={() => { streamRef.current?.close(); setRun(null); setSelected([]); setSavedJobs([]); setApprovedJobs([]); }}>Tạo phiên mới</AntButton>}</article></div>}</section>; }
