function RoleGuard({ teacher, children }) { return teacher ? children : <Navigate to="/student" replace />; }
function WorksheetExport({ onError }) {
  const { t } = useTranslation();
  const [form, setForm] = useState({ title: 'Phiếu bài tập', subject: 'Toán học', grade: 'Lớp 4', levels: [], types: ['multiple-choice', 'essay'], lessonIds: [] });
  const [lessons, setLessons] = useState([]); const [templates, setTemplates] = useState([]); const [candidates, setCandidates] = useState([]); const [selected, setSelected] = useState([]); const [modalMode, setModalMode] = useState(null); const [specs, setSpecs] = useState([{ type: 'multiple-choice', level: 'Dễ', count: 5, templateId: '' }]); const [busy, setBusy] = useState(false);
  useEffect(() => { const grade = form.grade.replace('Lớp ', ''); api(`/curriculum?grade=${encodeURIComponent(grade)}&subject=${encodeURIComponent(form.subject)}`).then(data => { setLessons(data.lessons || []); setForm(previous => ({ ...previous, lessonIds: previous.lessonIds.filter(id => (data.lessons || []).some(item => item.id === id)) })); }).catch(error => onError(error.message)); }, [form.grade, form.subject]);
  useEffect(() => { if (modalMode !== 'ai') { setTemplates([]); return; } api(`/worksheet/templates?grade=${encodeURIComponent(form.grade)}&subject=${encodeURIComponent(form.subject)}`).then(data => setTemplates(data.items || [])).catch(error => onError(error.message)); }, [modalMode, form.grade, form.subject, onError]);
  const toggle = (key, value) => setForm(previous => ({ ...previous, [key]: previous[key].includes(value) ? previous[key].filter(item => item !== value) : [...previous[key], value] }));
  const toggleQuestion = question => setSelected(previous => previous.some(item => item.id === question.id) ? previous.filter(item => item.id !== question.id) : [...previous, question]);
  async function search() { setBusy(true); try { const data = await api('/worksheet/search', { method: 'POST', body: JSON.stringify(form) }); setCandidates(data.items || []); } catch (error) { onError(error.message); } finally { setBusy(false); } }
  async function configure() { setBusy(true); try { const payload = { ...form, specs }; const data = modalMode === 'auto' ? await api('/worksheet/auto-select', { method: 'POST', body: JSON.stringify(payload) }) : await api('/worksheet/generate-ai', { method: 'POST', body: JSON.stringify(payload) }); setCandidates(data.items || []); setSelected(data.items || []); setModalMode(null); toast.success(modalMode === 'auto' ? 'Đã chọn câu hỏi từ kho.' : 'Đã tạo và lưu câu hỏi mới vào kho.'); } catch (error) { onError(error.message); } finally { setBusy(false); } }
  async function exportDocx() { if (!selected.length) return onError('Hãy chọn ít nhất một câu hỏi.'); setBusy(true); try { const response = await fetch(`${API}/worksheet/export`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: form.title, subject: form.subject, grade: form.grade, questionIds: selected.map(item => item.id) }) }); if (!response.ok) { const body = await response.json().catch(() => ({})); throw new Error(body.error?.message || body.error || 'Không thể xuất phiếu Word.'); } const blob = await response.blob(); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `${form.title || 'phieu-bai-tap'}.docx`; document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url); toast.success('Đã tải phiếu Word.'); } catch (error) { onError(error.message); } finally { setBusy(false); } }
  const questionTypeLabel = type => type === 'essay' ? t('worksheet.essay') : t('worksheet.multipleChoice');
  return <section className="content-page worksheet-page"><div className="dashboard-heading"><div><p className="eyebrow">{t('worksheet.eyebrow')}</p><h1>{t('worksheet.title')}</h1><p className="muted-copy">{t('worksheet.description')}</p></div><AntButton type="primary" loading={busy} disabled={!selected.length} onClick={exportDocx}>{t('worksheet.export')}</AntButton></div><article className="dashboard-panel worksheet-filters"><div className="form-grid"><label className="field wide">{t('worksheet.titleLabel')}<input value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} /></label><Select label={t('worksheet.subject')} value={form.subject} onChange={event => setForm({ ...form, subject: event.target.value, lessonIds: [] })}><option>Toán học</option><option>Tiếng Việt</option></Select><Select label={t('worksheet.grade')} value={form.grade} onChange={event => setForm({ ...form, grade: event.target.value, lessonIds: [] })}>{grades.map(item => <option key={item}>{item}</option>)}</Select><div className="wide filter-group"><b>{t('worksheet.levels')}</b><div>{levels.map(level => <label className="check inline-check" key={level}><input type="checkbox" checked={form.levels.includes(level)} onChange={() => toggle('levels', level)} />{level}</label>)}</div></div><div className="wide filter-group"><b>{t('worksheet.types')}</b><div><label className="check inline-check"><input type="checkbox" checked={form.types.includes('multiple-choice')} onChange={() => toggle('types', 'multiple-choice')} />{t('worksheet.multipleChoice')}</label><label className="check inline-check"><input type="checkbox" checked={form.types.includes('essay')} onChange={() => toggle('types', 'essay')} />{t('worksheet.essay')}</label></div></div><div className="wide"><PaginatedLessonPicker lessons={lessons} selected={form.lessonIds} onChange={lessonIds => setForm({ ...form, lessonIds })} label={t('worksheet.lessons')} /></div></div><div className="worksheet-actions"><AntButton loading={busy} onClick={search}>{t('worksheet.search')}</AntButton><AntButton loading={busy} onClick={() => setModalMode('auto')}>{t('worksheet.autoSelect')}</AntButton><AntButton type="primary" loading={busy} onClick={() => setModalMode('ai')}>{t('worksheet.generateAi')}</AntButton></div></article><article className="dashboard-panel"><div className="panel-heading"><div><p className="eyebrow">{t('worksheet.candidates')}</p><h2>{t('worksheet.selected', { count: selected.length })}</h2></div><AntTag color="purple">{candidates.length}</AntTag></div>{candidates.length ? <div className="worksheet-question-list">{candidates.map(question => <label key={question.id} className={`worksheet-question ${selected.some(item => item.id === question.id) ? 'selected' : ''}`}><input type="checkbox" checked={selected.some(item => item.id === question.id)} onChange={() => toggleQuestion(question)} /><span><b>{question.question}</b><small>{question.subject} · {question.grade} · {question.level} · {questionTypeLabel(question.type)}{question.lessonTitle ? ` · ${question.lessonTitle}` : ''}</small></span></label>)}</div> : <div className="empty-state compact"><span>◌</span><small>{t('worksheet.noQuestions')}</small></div>}</article>{modalMode && <div className="auth-overlay"><div className="auth-card worksheet-modal"><button className="close-auth" type="button" onClick={() => setModalMode(null)}>×</button><p className="eyebrow">{modalMode === 'ai' ? 'AI' : 'KHO CÂU HỎI'}</p><h2>{t('worksheet.configure')}</h2><p className="muted-copy">{modalMode === 'ai' ? t('worksheet.generating') : 'Chọn số lượng cho từng dạng câu hỏi.'}</p><div className="worksheet-specs">{specs.map((spec, index) => <div className="worksheet-spec-row" key={index}><Select label={t('worksheet.types')} value={spec.type} onChange={event => setSpecs(previous => previous.map((item, itemIndex) => itemIndex === index ? { ...item, type: event.target.value } : item))}><option value="multiple-choice">{t('worksheet.multipleChoice')}</option><option value="essay">{t('worksheet.essay')}</option></Select><Select label={t('worksheet.levels')} value={spec.level} onChange={event => setSpecs(previous => previous.map((item, itemIndex) => itemIndex === index ? { ...item, level: event.target.value } : item))}>{levels.map(level => <option key={level}>{level}</option>)}</Select><Select label={t('worksheet.template')} value={spec.templateId} onChange={event => setSpecs(previous => previous.map((item, itemIndex) => itemIndex === index ? { ...item, templateId: event.target.value } : item))}><option value="">Mặc định</option>{templates.filter(template => template.questionType === spec.type).map(template => <option key={template.id} value={template.id}>{template.title}</option>)}</Select><label className="field">{t('worksheet.count')}<input type="number" min="1" max="20" value={spec.count} onChange={event => setSpecs(previous => previous.map((item, itemIndex) => itemIndex === index ? { ...item, count: Number(event.target.value) } : item))} /></label>{specs.length > 1 && <button className="text-button danger" type="button" onClick={() => setSpecs(previous => previous.filter((_, itemIndex) => itemIndex !== index))}>Xóa</button>}</div>)}</div><div className="actions"><AntButton onClick={() => setSpecs(previous => [...previous, { type: 'multiple-choice', level: 'Dễ', count: 1, templateId: '' }])}>＋ {t('worksheet.addRow')}</AntButton><AntButton type="primary" loading={busy} onClick={configure}>{t('worksheet.confirm')}</AntButton></div></div></div>}</section>;
}
WorksheetExport = WorksheetExportEnhanced;
function ModuleLink({ to, children, end = false }) { return <NavLink to={to} end={end} className={({ isActive }) => `module-link${isActive ? ' active' : ''}`}>{children}</NavLink>; }
function RouterShell({ teacher, student, onAuth, onError }) {
  const { t } = useTranslation();
  const [authOpen, setAuthOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const isTeacherArea = location.pathname.startsWith('/teacher');
  const isTypingArea = location.pathname.startsWith('/student/typing');
  function openAuth() { setAuthOpen(true); }
  async function logout() { try { await api(teacher ? '/auth/logout' : '/student/logout', { method: 'POST' }); window.location.reload(); } catch (error) { onError(error.message); } }
  return <div className="app-shell">
    <aside className="app-sidebar">
      <div className="brand-lockup"><span className="brand-mark">✦</span><span>quizzz</span></div>
      <div className="brand-caption">{t('brand.caption')}</div>
      <nav className="module-nav">
        {(!teacher || student) && <div className="nav-group">
          <div className="nav-heading">{t('navigation.student')}</div>
          <ModuleLink to="/student" end>⌂ <span>{t('navigation.home')}</span></ModuleLink>
          <ModuleLink to="/student/typing">⌨ <span>{t('navigation.typing')}</span></ModuleLink>
          <ModuleLink to="/student/room">◉ <span>{t('navigation.room')}</span></ModuleLink>
          <ModuleLink to="/student/assignments">▣ <span>{t('navigation.assignments')}</span></ModuleLink>
          <ModuleLink to="/student/classes">♧ <span>{t('navigation.classes')}</span></ModuleLink>
        </div>}
        {teacher && <div className="nav-group">
          <div className="nav-heading">{t('navigation.teacher')}</div>
          <>
            <ModuleLink to="/teacher" end>◈ <span>{t('navigation.dashboard')}</span></ModuleLink>
            <ModuleLink to="/teacher/questions">☷ <span>{t('navigation.questions')}</span></ModuleLink>
            <ModuleLink to="/teacher/questions/ai">✦ <span>{t('navigation.ai')}</span></ModuleLink>
            <ModuleLink to="/teacher/quizzes">▤ <span>{t('navigation.quizzes')}</span></ModuleLink>
            <ModuleLink to="/teacher/worksheets">▤ <span>{t('navigation.worksheets')}</span></ModuleLink>
            <ModuleLink to="/teacher/assignments">↗ <span>{t('navigation.assign')}</span></ModuleLink>
            <ModuleLink to="/teacher/accounts">♙ <span>{t('navigation.accounts')}</span></ModuleLink>
            <ModuleLink to="/teacher/classes">♧ <span>{t('navigation.classList')}</span></ModuleLink>
            {teacher.role === 'admin' && <><ModuleLink to="/teacher/schools">🏫 <span>{t('navigation.schools')}</span></ModuleLink><ModuleLink to="/teacher/locations">⌖ <span>{t('navigation.locations')}</span></ModuleLink></>}
            <ModuleLink to="/teacher/realtime">◉ <span>{t('navigation.room')}</span></ModuleLink>
            <ModuleLink to="/teacher/reports">▥ <span>{t('navigation.reports')}</span></ModuleLink>
          </>
        </div>}
      </nav>
      <div className="sidebar-footer"><span className="status-dot" /> {t('common.online')}</div>
    </aside>
    <main className="app-main">
      <header className="app-header">
        <div><span className="breadcrumb">Quizzz</span><span className="route-title">{isTeacherArea ? t('brand.teacherSpace') : isTypingArea ? t('typing.title') : t('brand.studentSpace')}</span></div>
        <div className="header-actions"><span className="user-chip">{teacher ? t('brand.teacherChip', { name: teacher.displayName }) : student ? t('brand.studentChip', { name: student.nickname }) : t('common.guest')}</span>{teacher || student ? <><button className="auth-button" onClick={openAuth}>{t('common.changeAccount')}</button><button className="auth-button sign-out-button" onClick={logout}>{t('common.signOut')}</button></> : <button className="auth-button" onClick={openAuth}>{t('common.signIn')}</button>}</div>
      </header>
      <div className="page-content"><Notice text={onError.value} onClose={() => onError('')} />{location.pathname === '/teacher/accounts' ? <RoleGuard teacher={teacher}><AccountManagement teacher={teacher} onError={onError} /></RoleGuard> : location.pathname === '/teacher/schools' ? <RoleGuard teacher={teacher}><SchoolManagement onError={onError} /></RoleGuard> : location.pathname === '/teacher/locations' ? <RoleGuard teacher={teacher}><LocationManagement onError={onError} /></RoleGuard> : <Outlet />}</div>
    </main>
    {authOpen && <AuthModal onClose={() => setAuthOpen(false)} onSuccess={data => { onAuth(data); setAuthOpen(false); navigate(data.teacher ? '/teacher' : '/student'); }} onError={onError} />}
  </div>;
}
function RouterApp() { const [teacher, setTeacher] = useState(null); const [student, setStudent] = useState(null); const [error, setError] = useState(''); useEffect(() => { api('/auth/me').then(x => x.teacher && setTeacher(x.teacher)).catch(() => {}); api('/student/me').then(x => x.student && setStudent(x.student)).catch(() => {}); }, []); const errorHandler = value => setError(typeof value === 'string' ? value : value?.message || 'Có lỗi xảy ra.'); return <HashRouter><RouterShell teacher={teacher} student={student} onAuth={data => { if (data.teacher) setTeacher(data.teacher); if (data.student) setStudent(data.student); }} onError={errorHandler} /><Routes><Route element={<RouterShell teacher={teacher} student={student} onAuth={data => { if (data.teacher) setTeacher(data.teacher); if (data.student) setStudent(data.student); }} onError={errorHandler} />}><Route path="/" element={<Navigate to="/student" replace />} /><Route path="/student" element={<StudentHome onJoin={() => window.location.hash = '#/student/room'} />} /><Route path="/student/room" element={<StudentRoom onError={errorHandler} student={student} />} /><Route path="/student/assignments" element={<StudentAssignments onError={errorHandler} student={student} />} /><Route path="/student/classes" element={<JoinClass onError={errorHandler} student={student} />} /><Route path="/teacher" element={<RoleGuard teacher={teacher}><TeacherHome teacher={teacher} setView={() => {}} /></RoleGuard>} /><Route path="/teacher/questions" element={<RoleGuard teacher={teacher}><Questions onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/questions/ai" element={<RoleGuard teacher={teacher}><AiQuiz onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/quizzes" element={<RoleGuard teacher={teacher}><QuizSets onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/worksheets" element={<RoleGuard teacher={teacher}><WorksheetExport onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/assignments" element={<RoleGuard teacher={teacher}><Assignments onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/classes" element={<RoleGuard teacher={teacher}><Classes onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/realtime" element={<RoleGuard teacher={teacher}><Realtime onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/reports" element={<RoleGuard teacher={teacher}><Reports onError={errorHandler} /></RoleGuard>} /><Route path="*" element={<Navigate to="/student" replace />} /></Route></Routes></HashRouter>; }
function RouterAppFixed() { const [teacher, setTeacher] = useState(null); const [student, setStudent] = useState(null); const [error, setError] = useState(''); useEffect(() => { api('/auth/me').then(x => x.teacher && setTeacher(x.teacher)).catch(() => {}); api('/student/me').then(x => x.student && setStudent(x.student)).catch(() => {}); }, []); const errorHandler = value => setError(typeof value === 'string' ? value : value?.message || 'Có lỗi xảy ra.'); return <HashRouter><Routes><Route element={<RouterShell teacher={teacher} student={student} onAuth={data => { if (data.teacher) setTeacher(data.teacher); if (data.student) setStudent(data.student); }} onError={errorHandler} />}><Route path="/" element={<Navigate to="/student" replace />} /><Route path="/student" element={<StudentHome onJoin={() => window.location.hash = '#/student/room'} />} /><Route path="/student/typing" element={<TypingPractice />} /><Route path="/student/room" element={<StudentRoom onError={errorHandler} student={student} />} /><Route path="/student/assignments" element={<StudentAssignments onError={errorHandler} student={student} />} /><Route path="/student/classes" element={<JoinClass onError={errorHandler} student={student} />} /><Route path="/teacher" element={<RoleGuard teacher={teacher}><TeacherHome teacher={teacher} setView={() => {}} /></RoleGuard>} /><Route path="/teacher/questions" element={<RoleGuard teacher={teacher}><Questions onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/questions/ai" element={<RoleGuard teacher={teacher}><AiQuiz onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/quizzes" element={<RoleGuard teacher={teacher}><QuizSets onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/worksheets" element={<RoleGuard teacher={teacher}><WorksheetExport onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/assignments" element={<RoleGuard teacher={teacher}><Assignments onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/classes" element={<RoleGuard teacher={teacher}><Classes onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/accounts" element={<></>} /><Route path="/teacher/schools" element={<></>} /><Route path="/teacher/locations" element={<></>} /><Route path="/teacher/realtime" element={<RoleGuard teacher={teacher}><Realtime onError={errorHandler} /></RoleGuard>} /><Route path="/teacher/reports" element={<RoleGuard teacher={teacher}><Reports onError={errorHandler} /></RoleGuard>} /><Route path="*" element={<Navigate to="/student" replace />} /></Route></Routes></HashRouter>; }
const nativePushState = window.history.pushState.bind(window.history);
window.history.pushState = (...args) => { nativePushState(...args); window.dispatchEvent(new PopStateEvent('popstate')); };
QuizSets = QuizSetManagement;
Classes = ClassManagement;
function PreferenceSwitcher({ mode, onThemeChange }) {
  const { t } = useTranslation();
  const [locale, setLocale] = useState(i18n.language?.startsWith('en') ? 'en' : 'vi');
  async function changeLanguage(event) { const next = event.target.value; await i18n.changeLanguage(next); localStorage.setItem('quizzz.locale', next); setLocale(next); }
  return <div className="preference-switcher" aria-label={t('theme.label')}>
    <div className="theme-switcher" role="group" aria-label={t('theme.label')}>
      <button type="button" className={mode === 'light' ? 'active' : ''} aria-pressed={mode === 'light'} onClick={() => onThemeChange('light')} title={t('theme.useLight')}>☀ <span>{t('theme.light')}</span></button>
      <button type="button" className={mode === 'dark' ? 'active' : ''} aria-pressed={mode === 'dark'} onClick={() => onThemeChange('dark')} title={t('theme.useDark')}>☾ <span>{t('theme.dark')}</span></button>
    </div>
    <label className="language-switcher" title={t('common.language')}><span>文</span><select value={locale} onChange={changeLanguage} aria-label={t('common.language')}><option value="vi">VI</option><option value="en">EN</option></select></label>
  </div>;
}
function AppProviders() {
  const [mode, setMode] = useState(() => localStorage.getItem('quizzz.theme') === 'dark' ? 'dark' : 'light');
  useEffect(() => { document.documentElement.dataset.theme = mode; localStorage.setItem('quizzz.theme', mode); }, [mode]);
  const isDark = mode === 'dark';
  return <ConfigProvider theme={{ algorithm: isDark ? antdTheme.darkAlgorithm : antdTheme.defaultAlgorithm, token: { colorPrimary: '#16aee5', colorInfo: '#16aee5', borderRadius: 10, fontFamily: "'Plus Jakarta Sans', Inter, system-ui, sans-serif" }, components: { Button: { controlHeight: 40, fontWeight: 700 }, Card: { borderRadiusLG: 16 }, Table: { headerBg: isDark ? '#162a3a' : '#e5f7fd' } } }}><QueryClientProvider client={queryClient}><RouterAppFixed /><PreferenceSwitcher mode={mode} onThemeChange={setMode} /><Toaster position="top-right" richColors closeButton theme={mode} /></QueryClientProvider></ConfigProvider>;
}
createRoot(document.getElementById('root')).render(<AppProviders />);
